"""csc_lib: Candidate-Signature Consensus (CSC) for gold-free NL->FOL faithfulness (iteration 4, T6-P).

WHAT CSC MEASURES. Peers from k = 3 other model families translate the SAME sentence after being shown the
CANDIDATE's own symbol list (predicate and constant names with arities, shuffled deterministically). A peer agrees
when its formula is z3-equivalent to the candidate with NO aligner: symbol names are matched case-insensitively
(key = (lower(name), arity)) and nothing else. Because the peers are cued with the candidate's vocabulary, the
rename/vocabulary problem of free consensus disappears by construction: an equivalent translation in the same
vocabulary is exact-equivalent. The price is ANCHORING: a peer may copy a wrong symbol from the list (a foreign
conjunct, a wrong-meaning predicate) and thereby endorse an error. This library measures both sides.

Orientation everywhere: HIGHER score = MORE LIKELY ERROR.

  c_csc        = 1 - (#peers exact-equivalent to the candidate) / (#peers with a parseable formula).
                 z3 UNKNOWN (2 s timeout) counts as NOT equivalent and is recorded in n_unknown.
                 < 2 parseable peers -> 0.5 with status 'csc_insufficient_peers'.
                 Unparseable candidate -> 1.0 with status 'UNPARSEABLE' (coverage view; never silently dropped).
  c_csc_multi  = the same, but peer p also endorses when its SECOND reading (alt_fol) is equivalent to the candidate
                 AND another peer q != p produced that reading too (fol or alt) - a corroborated alternative reading.
  c_csc_graded = exp-5 / exp-8 peer_text.graded_consensus over claim units with the IDENTITY symbol map
                 (1 - F1(support, coverage)); unit entailment by the finite-model refuter then z3.
Blind spots (stated): errors every cued peer copies from the list (anchoring; measured on PERTURB ADD_FOREIGN /
MEANING_RENAME); errors shared by the peers independently of the cue; readings no peer produces.
Cost: k API calls per unique (sentence, signature); z3 CPU seconds per candidate (MARGINAL cost).
"""
from __future__ import annotations

import hashlib
import itertools
import json
import random
import re
import sys
from pathlib import Path

SRC = Path(__file__).resolve().parent
ROOT = SRC.parent
V8 = SRC / "vendor_x8"
if str(V8) not in sys.path:
    sys.path.insert(0, str(V8))
import peer_text as PT  # noqa: E402  (installs the dataset-E parser as module 'fol'; adds vendor_c / vendor_a)
import fol as EFOL  # noqa: E402  (== vendor_e.fol, the dataset-E parser)
sys.path.insert(0, str(V8 / "vendor_c"))
import repair_census as RC  # noqa: E402  (vendor_c: atoms, symbols, fp, edits, search)

PROMPT_PATH = ROOT / "data" / "prompts" / "fewshot_v1.txt"
PEERS = [("deepseek/deepseek-v3.2", "deepseek", {"reasoning": {"enabled": False}}),
         ("microsoft/phi-4", "microsoft", {}),
         ("openai/gpt-4.1-mini", "openai", {}),
         ("qwen/qwen3-235b-a22b-2507", "qwen", {})]
PEER_MODELS = [p[0] for p in PEERS]
PEER_FAMILY = {p[0]: p[1] for p in PEERS}
PEER_EXTRA = {p[0]: p[2] for p in PEERS}
BLOCK_TEMPLATE = ("Symbols from another translation of this sentence (name/arity, random order): {items}. "
                  "Use a listed symbol wherever its name fits what the sentence says, and keep its arity. "
                  "If part of the sentence is not covered by any listed symbol, introduce a new symbol. "
                  "You need not use every listed symbol. The list is not a translation: translate the sentence "
                  "itself. Return JSON {{\"fol\": <formula>, \"alt_fol\": <a formula for a second legitimate "
                  "reading, or null>}}.")
V1B_PREFIX = "For this sentence, a symbol list IS given: "
Z3_MS = 2000


def block_template_sha256() -> str:
    return hashlib.sha256(BLOCK_TEMPLATE.encode()).hexdigest()


# ============================================================================================ parse / signature
def parse(s: str | None):
    """Dataset-E parser -> AST or None (unparseable)."""
    return PT.parse_fol(s)


def _bound(e, acc=None):
    return RC.bound_vars(e, acc)


def extract_signature_ast(e) -> list[tuple[str, int]]:
    """Symbols of a parsed formula: predicates (name, arity >= 0 for propositional atoms) and constants (name, 0);
    bound variables excluded. Sorted by (lower(name), arity, name); one entry per lowercase key (first spelling wins)."""
    P, C = RC.symbols(e)
    items = sorted(set(P) | {(c, 0) for c in C}, key=lambda t: (t[0].lower(), t[1], t[0]))
    out, seen = [], set()
    for n, a in items:
        k = (n.lower(), a)
        if k not in seen:
            seen.add(k)
            out.append((n, a))
    return out


def extract_signature(fol: str) -> list[tuple[str, int]]:
    """(name, arity) list of the formula's predicates and constants (arity 0), variables excluded; [] if unparseable."""
    e = parse(fol)
    return [] if e is None else extract_signature_ast(e)


def sig_lower(sig) -> list[tuple[str, int]]:
    return sorted({(n.lower(), a) for n, a in sig})


def sig_string(sig) -> str:
    return "|".join(f"{n}/{a}" for n, a in sig_lower(sig))


def sig_key(sig) -> str:
    return hashlib.sha1(sig_string(sig).encode()).hexdigest()[:16]


# ============================================================================================ prompt
_PROMPT_CACHE: dict = {}


def _prompt() -> dict:
    if "p" not in _PROMPT_CACHE:
        _PROMPT_CACHE["p"] = json.loads(PROMPT_PATH.read_text())
    return _PROMPT_CACHE["p"]


def symbols_block(text: str, sig, variant: str = "v1") -> str:
    """The appended CSC block; the list order is a deterministic shuffle seeded by sha1(text | canonical signature)."""
    items = [f"{n}/{a}" for n, a in sorted(sig, key=lambda t: (t[0].lower(), t[1], t[0]))]
    rng = random.Random(int(hashlib.sha1((text + "|" + sig_string(sig)).encode()).hexdigest(), 16))
    rng.shuffle(items)
    b = BLOCK_TEMPLATE.format(items=", ".join(items))
    return (V1B_PREFIX + b) if variant == "v1b" else b


def csc_prompt(text: str, signature, variant: str = "v1") -> list[dict]:
    """Messages: the byte-identical dataset-E few-shot prompt (system + 6 exemplars) + the user turn
    'Sentence: <text>' followed by a blank line and the symbols block."""
    pr = _prompt()
    user = pr["user_template"].replace("{sentence}", text) + "\n\n" + symbols_block(text, signature, variant)
    return [{"role": "system", "content": pr["system"]}] + list(pr["exemplars"]) + [{"role": "user", "content": user}]


def free_prompt(text: str) -> list[dict]:
    pr = _prompt()
    return [{"role": "system", "content": pr["system"]}] + list(pr["exemplars"]) + \
        [{"role": "user", "content": pr["user_template"].replace("{sentence}", text)}]


# ============================================================================================ peer output parsing
_FENCE = re.compile(r"```(?:json)?", re.I)


def _clean_formula(s):
    if s is None:
        return None
    if not isinstance(s, str):
        return None
    s = s.strip()
    if s.lower() in ("", "null", "none", "n/a"):
        return None
    if s.startswith("FOL:"):
        s = s[4:].strip()
    return s


def parse_peer(raw: str | None) -> dict:
    """Peer raw output -> {'fol', 'alt_fol', 'format' in {json, fol_line, bare, fail}}.
    (1) first JSON object (```json fences tolerated) with a string 'fol'; (2) a 'FOL:' line (alt = None);
    (3) the whole output if it is a single line that parses as a formula ('bare'); else fail."""
    s = (raw or "").strip()
    if not s:
        return {"fol": None, "alt_fol": None, "format": "fail"}
    t = _FENCE.sub("", s)
    dec = json.JSONDecoder()
    for m in re.finditer(r"\{", t):
        try:
            obj, _ = dec.raw_decode(t[m.start():])
        except json.JSONDecodeError:
            continue
        if isinstance(obj, dict) and isinstance(obj.get("fol"), str) and obj.get("fol").strip():
            return {"fol": _clean_formula(obj.get("fol")), "alt_fol": _clean_formula(obj.get("alt_fol")), "format": "json"}
    for line in s.splitlines():
        if line.strip().startswith("FOL:"):
            return {"fol": line.split("FOL:", 1)[1].strip() or None, "alt_fol": None, "format": "fol_line"}
    lines = [x for x in t.splitlines() if x.strip()]
    if len(lines) == 1 and parse(lines[0].strip()) is not None:
        return {"fol": lines[0].strip(), "alt_fol": None, "format": "bare"}
    return {"fol": None, "alt_fol": None, "format": "fail"}


# ============================================================================================ exact equivalence
def lower_ast(e, bv=frozenset()):
    """Lower-case every predicate and constant name (bound variables untouched)."""
    k = e[0]
    if k == "atom":
        return ("atom", e[1].lower(), tuple(x if x in bv else x.lower() for x in e[2]))
    if k in ("all", "ex"):
        return (k, e[1], lower_ast(e[2], bv | {e[1]}))
    if k == "not":
        return ("not", lower_ast(e[1], bv))
    return (k, lower_ast(e[1], bv), lower_ast(e[2], bv))


def prep(s: str | None):
    """Parse + lowercase -> (ast, canonical string, fingerprint) or None."""
    e = parse(s)
    if e is None:
        return None
    el = lower_ast(e)
    try:
        f = RC.fp(el)
    except RecursionError:
        f = None
    return el, PT.canon(el), f


def eq_prepped(a, b, ms: int = Z3_MS):
    """a, b from prep(). True / False / None (UNKNOWN). Canonical-string identity -> True; different random-model
    fingerprints -> False (sound: they differ on a finite model); else z3 with `ms` timeout."""
    if a is None or b is None:
        return None
    if a[1] == b[1]:
        return True
    if a[2] is not None and b[2] is not None and a[2] != b[2]:
        return False
    try:
        return EFOL.equivalent(a[0], b[0], ms=ms)
    except (Exception,):  # noqa: BLE001 - z3 exceptions / recursion on huge formulas -> UNKNOWN (counted)
        return None


def eq_exact(fa: str, fb: str, ms: int = Z3_MS):
    """Exact (no aligner) case-insensitive z3 equivalence of two formula strings: True / False / None (UNKNOWN or
    unparseable)."""
    return eq_prepped(prep(fa), prep(fb), ms)


# ============================================================================================ scores
def consensus_score(text: str, fol: str, peers: list[dict | str], mode: str = "csc", ms: int = Z3_MS,
                    _prepped: dict | None = None) -> dict:
    """Binary CSC. peers: formula strings or dicts with 'fol'. Returns {'c', 'per_peer', 'n_used', 'n_unknown',
    'n_unparseable_peers', 'status'} with c = 1 - agree/used (higher = more likely error)."""
    assert mode == "csc", mode
    pp = _prepped if _prepped is not None else {}
    cand = pp.get(fol) if fol in pp else prep(fol)
    fols = [p.get("fol") if isinstance(p, dict) else p for p in peers]
    usable = []
    n_bad = 0
    for f in fols:
        x = pp.get(f) if f in pp else prep(f)
        if x is None:
            n_bad += 1
        else:
            usable.append(x)
    if cand is None:
        return {"c": 1.0, "per_peer": [], "n_used": len(usable), "n_unknown": 0, "n_unparseable_peers": n_bad,
                "status": "UNPARSEABLE"}
    if len(usable) < 2:
        return {"c": 0.5, "per_peer": [], "n_used": len(usable), "n_unknown": 0, "n_unparseable_peers": n_bad,
                "status": "csc_insufficient_peers"}
    verd = [eq_prepped(cand, x, ms) for x in usable]
    n_true = sum(v is True for v in verd)
    return {"c": 1 - n_true / len(usable), "per_peer": verd, "n_used": len(usable),
            "n_unknown": sum(v is None for v in verd), "n_unparseable_peers": n_bad, "status": "OK"}


def csc_multi_score(text: str, fol: str, peer_records: list[dict], ms: int = Z3_MS) -> dict:
    """Multi-reading CSC. Peer p endorses iff eq(cand, p.fol) OR (p.alt parseable AND eq(cand, p.alt) AND some other
    peer q != p has eq(p.alt, q.fol) or eq(p.alt, q.alt)). Denominator = peers with a parseable fol."""
    cand = prep(fol)
    P = []
    for r in peer_records:
        f = prep(r.get("fol"))
        if f is None:
            continue
        P.append((f, prep(r.get("alt_fol")) if r.get("alt_fol") else None))
    if cand is None:
        return {"c": 1.0, "status": "UNPARSEABLE", "n_used": len(P), "n_alt_endorse": 0}
    if len(P) < 2:
        return {"c": 0.5, "status": "csc_insufficient_peers", "n_used": len(P), "n_alt_endorse": 0}
    endorse, n_alt = 0, 0
    for i, (f, alt) in enumerate(P):
        if eq_prepped(cand, f, ms) is True:
            endorse += 1
            continue
        if alt is not None and eq_prepped(cand, alt, ms) is True:
            ok = False
            for j, (g, galt) in enumerate(P):
                if j == i:
                    continue
                if eq_prepped(alt, g, ms) is True or (galt is not None and eq_prepped(alt, galt, ms) is True):
                    ok = True
                    break
            if ok:
                endorse += 1
                n_alt += 1
    return {"c": 1 - endorse / len(P), "status": "OK", "n_used": len(P), "n_alt_endorse": n_alt}


def _identity_pair(a_s: str, b_s: str, ent, eqv) -> dict:
    """pairs.py-format record with the IDENTITY map: fwd = [b ⊨ unit of a], bwd = [a ⊨ unit of b]."""
    au = PT.units_of(a_s)[0]
    bu = PT.units_of(b_s)[0]
    if a_s == b_s:
        return {"fwd": [True] * len(au), "bwd": [True] * len(bu), "peer_r": b_s, "peer_units_r": list(bu),
                "equiv": True, "cost": 0.0, "n_maps": 0, "rank": 0}
    return {"fwd": [ent(b_s, u) for u in au], "bwd": [ent(a_s, v) for v in bu], "peer_r": b_s,
            "peer_units_r": list(bu), "equiv": eqv, "cost": 0.0, "n_maps": 1, "rank": 0}


_ENT = {}


def _entailer(ms: int = Z3_MS):
    if ms not in _ENT:
        _ENT[ms] = PT.Entailer(ms)
    return _ENT[ms]


def graded_consensus(text: str, fol: str, peers: list[dict | str], mode: str = "csc", ms: int = Z3_MS) -> dict:
    """Graded CSC: exp-8 peer_text.graded_consensus with the identity symbol map on lower-cased canonical formulas.
    g = 1 - F1(support, coverage) (higher = more likely error); support = share of candidate claim units entailed by
    the peers; coverage = share of the peers' majority units the candidate entails."""
    assert mode == "csc", mode
    cand = prep(fol)
    fols = [p.get("fol") if isinstance(p, dict) else p for p in peers]
    ps = [x for x in (prep(f) for f in fols) if x is not None]
    if cand is None:
        return {"g": 1.0, "status": "UNPARSEABLE"}
    if len(ps) < 2:
        return {"g": 0.5, "status": "csc_insufficient_peers"}
    ent = _entailer(ms)
    cs = cand[1]
    pool = [p[1] for p in ps]
    by = {cs: cand}
    for p in ps:
        by[p[1]] = p
    table = {}
    for a in sorted(set([cs] + pool)):
        for b in pool:
            if a == b or (a, b) in table:
                continue
            table[(a, b)] = _identity_pair(a, b, ent, eq_prepped(by[a], by[b], ms))
    try:
        g = PT.graded_consensus(cs, pool, table, ent, return_codes=True)
    except (RecursionError, KeyError, ValueError) as ex:
        return {"g": None, "status": f"GRADED_FAIL:{type(ex).__name__}"}
    return {"g": g["g_score"], "support": g.get("support"), "coverage": g.get("coverage"),
            "unit_codes": [c["code"] for c in g.get("unit_codes", [])], "status": "OK"}


def peer_majority(peers: list[dict | str], ms: int = Z3_MS) -> dict:
    """Exact-equivalence classes among parseable peers (given in P order). Majority = a class with >= 2 members;
    a 2-2 tie (k = 4) is broken by the earliest P member. Returns {'formula' (the earliest member's fol) | None,
    'status' in {MAJORITY, NO_MAJORITY, INSUFFICIENT}, 'class_sizes'}."""
    fols = [p.get("fol") if isinstance(p, dict) else p for p in peers]
    items = [(i, f, prep(f)) for i, f in enumerate(fols)]
    items = [t for t in items if t[2] is not None]
    if len(items) < 2:
        return {"formula": None, "status": "INSUFFICIENT", "class_sizes": [len(items)] if items else []}
    classes: list[list] = []
    for t in items:
        for c in classes:
            if eq_prepped(c[0][2], t[2], ms) is True:
                c.append(t)
                break
        else:
            classes.append([t])
    best = sorted(classes, key=lambda c: (-len(c), c[0][0]))[0]
    sizes = sorted((len(c) for c in classes), reverse=True)
    if len(best) >= 2:
        return {"formula": best[0][1], "status": "MAJORITY", "class_sizes": sizes, "n_classes": len(classes)}
    return {"formula": None, "status": "NO_MAJORITY", "class_sizes": sizes, "n_classes": len(classes)}


def symbol_usage(sig, peer_fols: list[str | None]) -> list[list[bool]]:
    """For each listed symbol s (in `sig` order) and each parseable peer: used = (lower(name), arity) of s occurs among
    the peer's predicates/constants. Returns [[used for peer in parseable peers] for s in sig]."""
    psyms = []
    for f in peer_fols:
        e = parse(f)
        if e is None:
            continue
        psyms.append(set(sig_lower(extract_signature_ast(e))))
    return [[(n.lower(), a) in ps for ps in psyms] for n, a in sig]


# ============================================================================================ same-vocab typed repair
def _subst(e, a: tuple, b: str):
    k = e[0]
    if k == "atom":
        return ("atom", b, e[2]) if (e[1], len(e[2])) == a else e
    if k in ("all", "ex"):
        return (k, e[1], _subst(e[2], a, b))
    if k == "not":
        return ("not", _subst(e[1], a, b))
    return (k, _subst(e[1], a, b), _subst(e[2], a, b))


def edits_ext(e, target):
    """repair_census.edits + SUBST (replace every occurrence of predicate a (absent from the target) by a target
    predicate b of the same arity (absent from e)) + ADD_ANY (conjoin ANY target atom whose predicate already occurs
    in e, or any NEGATED target literal, re-binding foreign variables to in-scope ones exactly like ADD)."""
    yield from RC.edits(e, target)
    Pe, _ = RC.symbols(e)
    Pt, Ct = RC.symbols(target)
    for a in sorted(Pe - Pt):
        for b in sorted(Pt - Pe):
            if a[1] == b[1]:
                yield "SUBST", _subst(e, a, b[0])
    # literals to add: positive target atoms whose predicate already occurs in e (new-predicate positives are ADD's),
    # plus every NEGATED target literal (extension: a dropped '¬P(x)' condition is otherwise unreachable at depth 1)
    lits, seen = [], set()
    for at in RC.atoms(target):
        if (at[1], len(at[2])) in Pe and (False, at) not in seen:
            seen.add((False, at))
            lits.append((False, at))
    for _p, nd, _s in RC.subterms(target):
        if nd[0] == "not" and nd[1][0] == "atom" and (True, nd[1]) not in seen:
            seen.add((True, nd[1]))
            lits.append((True, nd[1]))
    for path, node, scope in list(RC.subterms(e)):
        for neg, at in lits:
            sc = list(scope)
            opts = [[x] if (x in Ct or x in sc) else (sc or [x]) for x in at[2]]
            for combo in itertools.islice(itertools.product(*opts), 6):
                lit = ("atom", at[1], tuple(combo))
                yield "ADD_ANY", RC.replace(e, path, ("and", node, ("not", lit) if neg else lit))


def _search_ext(ao, target, budget_s: float, max_d2: int = 6000):
    import time
    ft = RC.fp(target)
    t0 = time.time()
    lvl1, seen = [], set()
    for lab, c in edits_ext(ao, target):
        s = str(c)
        if s in seen:
            continue
        seen.add(s)
        lvl1.append((lab, c))
        if RC.fp(c) == ft and EFOL.equivalent(c, target, ms=1500) is True:
            return [lab], time.time() - t0, False
        if time.time() - t0 > budget_s:
            return None, time.time() - t0, True
    n = 0
    for lab1, c1 in lvl1:
        for lab2, c2 in edits_ext(c1, target):
            n += 1
            if lab1 == "NEG" and lab2 == "NEG":
                continue
            if n > max_d2 * 10 or time.time() - t0 > budget_s:
                return None, time.time() - t0, True
            if RC.fp(c2) == ft and EFOL.equivalent(c2, target, ms=1500) is True:
                return sorted([lab1, lab2]), time.time() - t0, False
    return None, time.time() - t0, False


def typed_repair_same_vocab(fol: str, target: str, budget_s: float = 6.0) -> dict:
    """Smallest typed edit sequence (depth <= 2) turning `fol` into a formula exact-equivalent (lower-cased, same
    vocabulary, NO align/gran bridge) to `target`. Operators: NEG REV QUANT RESTR CONN MOVE DROP ADD SWAP BIND SCOPE
    UNGLUE (repair_census) + SUBST + ADD_ANY. The ops repair `fol` TOWARDS `target` (an extra conjunct in `fol` is
    repaired by DROP). Returns {'cls': EQUIV | '<OP>[+<OP>]' | NO_REPAIR | TIMEOUT | PARSE_FAIL | ERROR, 'ops', 'secs'}."""
    import time
    t0 = time.time()
    a, b = prep(fol), prep(target)
    if a is None or b is None:
        return {"cls": "PARSE_FAIL", "ops": [], "secs": 0.0}
    try:
        if eq_prepped(a, b) is True:
            return {"cls": "EQUIV", "ops": [], "secs": round(time.time() - t0, 3)}
        ops, dt, timed_out = _search_ext(a[0], b[0], budget_s)
        if ops:
            return {"cls": "+".join(ops), "ops": ops, "secs": round(time.time() - t0, 3)}
        return {"cls": "TIMEOUT" if timed_out else "NO_REPAIR", "ops": [], "secs": round(time.time() - t0, 3)}
    except (RecursionError, ValueError, KeyError, IndexError, TypeError) as ex:
        return {"cls": "ERROR", "ops": [], "err": f"{type(ex).__name__}: {str(ex)[:80]}", "secs": round(time.time() - t0, 3)}


# ============================================================================================ peers (API)
def peer_assignment(candidate_family: str | None) -> dict:
    """K3 = the first 3 members of P whose family != candidate_family; K4 = all of P only if candidate_family is not
    a P family (else None). PERTURB rows (no generator family) -> K3 = deepseek, microsoft, openai; K4 adds qwen."""
    k3 = [m for m in PEER_MODELS if PEER_FAMILY[m] != candidate_family][:3]
    k4 = list(PEER_MODELS) if candidate_family not in set(PEER_FAMILY.values()) else None
    return {"k3": k3, "k4": k4}


def csc_peers(text: str, signature, families: list[str] | None = None, k: int = 3, candidate_family: str | None = None,
              client=None, dry_run: bool = True, variant: str = "v1") -> dict:
    """Generate CSC peers for (text, signature). dry_run=True -> {'models', 'estimate_usd', 'messages'} (no call).
    Otherwise runs the async OpenRouter client (src/llm.py; cached, budget-checked) and returns
    {'peers': [{model, family, raw, fol, alt_fol, format, parse_ok, cost}], 'cost_usd'}."""
    asg = peer_assignment(candidate_family)
    models = families or (asg["k3"] if k == 3 else (asg["k4"] or asg["k3"]))
    msgs = csc_prompt(text, signature, variant)
    est = {"deepseek/deepseek-v3.2": 3.2e-4, "microsoft/phi-4": 1.1e-4, "openai/gpt-4.1-mini": 5.6e-4,
           "qwen/qwen3-235b-a22b-2507": 1.6e-4}
    if dry_run:
        return {"models": models, "estimate_usd": sum(est.get(m, 5e-4) for m in models), "messages": msgs}
    import asyncio
    import aiohttp
    import or_client as llm

    async def run():
        cl = client or llm.Client(stage="csc_peers_lib")
        async with aiohttp.ClientSession() as s:
            return await asyncio.gather(*[cl.chat(s, m, msgs, PEER_EXTRA[m]) for m in models])
    recs = asyncio.run(run())
    out, tot = [], 0.0
    for m, r in zip(models, recs):
        pr = parse_peer(r.get("content"))
        out.append({"model": m, "family": PEER_FAMILY[m], "raw": r.get("content"), **pr,
                    "parse_ok": prep(pr["fol"]) is not None, "cost": 0.0 if r.get("cache_hit") else r.get("cost_usd", 0.0)})
        tot += out[-1]["cost"] or 0.0
    return {"peers": out, "cost_usd": tot}

source_files.vendor_x8/pairs.py:
"""PEER_HYB pair engine (iteration 3, T3): pair-level ALIGN / NF-anchored / HYB verdicts and per-row consensus scores.

For every sentence task we compute, for each ordered pair (a, b) with a in {candidates} ∪ pool and b in pool, a != b:
  align_eq = vendor_c common.eqmv(parse(a), parse(b))   (EXACTLY the call exp 5 pool_scoring.score_sentence makes for
             c_score_align, symmetric, 30 s SIGALRM cap -> None)
  nf       = peer_text.pair_result(a, b, ent, text, variant='NF-anchored', k=5, tau=0.5)   (exp 5 NF-anchored)
  al       = peer_text.pair_result(a, b, ent, variant='ALIGN')                             (exp 5 graded ALIGN)
  hyb_eq   = True if align_eq is True or nf['equiv'] is True; False if both are False; else None (UNKNOWN, never agreement)
Row scores (leave-one-FAMILY-out pool P_c, as exp 5):
  c_align = 1 - #(align_eq True)/|P_c|   c_nf = graded_consensus(NF pairs)['c_score_nf']   c_hyb = 1 - #(hyb_eq True)/|P_c|
  g_align = graded_consensus(ALIGN pairs)  g_nf = graded_consensus(NF pairs)
  g_hyb   = graded_consensus over a composite pair table: ALIGN record if align_eq True, else NF record if nf_eq True,
            else whichever record has more verified (True) unit entailments fwd+bwd (ties -> ALIGN).  Pre-registered.
All scores are NA (None) when |P_c| < 2 (peer_unavailable). Unparseable candidates get coverage_status UNPARSEABLE.
Identical canonical strings are True in every mode (exp C gotcha).
"""
from __future__ import annotations

import hashlib
import json
import os
import resource
import signal
import sqlite3
import sys
import time
from pathlib import Path

SRC = Path(__file__).resolve().parent
ROOT = SRC.parent
if str(SRC) not in sys.path:
    sys.path.insert(0, str(SRC))
os.environ.setdefault("NLTK_DATA", str(ROOT / "data" / "nltk_data"))
import peer_text as PT  # noqa: E402

CACHE_DB = ROOT / "cache" / "pair_cache.sqlite"


class _TO(Exception):
    pass


def _alarm(signum, frame):  # noqa: ARG001
    raise _TO()


def init_worker(mem_gb: float = 3.5):
    os.environ["PYTHONHASHSEED"] = "0"
    try:
        resource.setrlimit(resource.RLIMIT_AS, (int(mem_gb * 1024 ** 3), int(mem_gb * 1024 ** 3)))
    except (ValueError, OSError):
        pass
    signal.signal(signal.SIGALRM, _alarm)


def _with_alarm(secs: int, fn, *a, **kw):
    signal.signal(signal.SIGALRM, _alarm)
    signal.alarm(secs)
    try:
        return fn(*a, **kw), False
    except _TO:
        return None, True
    finally:
        signal.alarm(0)


def sha1(s: str) -> str:
    return hashlib.sha1(s.encode()).hexdigest()


# ------------------------------------------------------------------------------------------------ sqlite pair cache
class PairCache:
    """Pair cache keyed by (mode, sha1(a), sha1(b), sha1(text) for NF). Workers use an in-memory dict preloaded by the
    parent (`preload`) and return their new entries; ONLY the parent process writes the sqlite file (single writer: the
    workspace sits on a network filesystem where multi-process WAL is unsafe). Values are JSON pair records."""

    def __init__(self, preload: dict | None = None, enabled: bool = True):
        self.enabled = enabled
        self.mem: dict = dict(preload or {})
        self.new: dict = {}

    @staticmethod
    def key(mode: str, a: str, b: str, text: str | None) -> str:
        return f"{mode}|{sha1(a)}|{sha1(b)}|{sha1(text) if (mode == 'NF-anchored' and text) else '-'}"

    def get(self, mode, a, b, text=None):
        return self.mem.get(self.key(mode, a, b, text)) if self.enabled else None

    def put(self, mode, a, b, text, v):
        if not self.enabled:
            return
        k = self.key(mode, a, b, text)
        self.mem[k] = v
        self.new[k] = v

    def flush(self):  # kept for API symmetry; persistence is done by the parent (store_pairs / load_pairs)
        return


def open_db(path: Path = CACHE_DB) -> sqlite3.Connection:
    path.parent.mkdir(parents=True, exist_ok=True)
    con = sqlite3.connect(str(path), timeout=120)
    con.execute("CREATE TABLE IF NOT EXISTS pc (k TEXT PRIMARY KEY, v TEXT)")
    con.commit()
    return con


def store_pairs(con: sqlite3.Connection, new: dict):
    if new:
        con.executemany("INSERT OR REPLACE INTO pc (k, v) VALUES (?, ?)", [(k, json.dumps(v, ensure_ascii=False)) for k, v in new.items()])
        con.commit()


def load_pairs(con: sqlite3.Connection, keys: list[str]) -> dict:
    out = {}
    for i in range(0, len(keys), 500):
        chunk = keys[i:i + 500]
        q = "SELECT k, v FROM pc WHERE k IN (%s)" % ",".join("?" * len(chunk))
        for k, v in con.execute(q, chunk):
            out[k] = json.loads(v)
    return out


def preload_keys(text: str, pool_strings: list[str]) -> list[str]:
    """Cache keys of every peer-peer pair of a sentence (all modes), for reuse across scoring passes."""
    ks = []
    for a in pool_strings:
        for b in pool_strings:
            if a == b:
                continue
            ks += [PairCache.key("ALIGN", a, b, None), PairCache.key("NF-anchored", a, b, text)]
            if a < b:
                ks.append(PairCache.key("EQMV", a, b, None))
    return ks


# ------------------------------------------------------------------------------------------------ pair verdicts
def _unknown_pair(cand_s: str, peer_s: str) -> dict:
    return {"fwd": [None] * len(PT.units_of(cand_s)[0]), "bwd": [None] * len(PT.units_of(peer_s)[0]), "peer_r": peer_s,
            "peer_units_r": list(PT.units_of(peer_s)[0]), "equiv": None, "cost": None, "n_maps": 0, "rank": None,
            "timeout": True}


def _slim(r: dict) -> dict:
    return {k: r.get(k) for k in ("fwd", "bwd", "peer_r", "peer_units_r", "equiv", "cost", "n_maps", "rank", "timeout")}


def n_true(r: dict | None) -> int:
    if r is None:
        return 0
    return sum(x is True for x in r["fwd"]) + sum(x is True for x in r["bwd"])


def hyb_of(a_eq, n_eq):
    """OR with UNKNOWN: True if either True; False if both False; else None (never counts as agreement)."""
    if a_eq is True or n_eq is True:
        return True
    if a_eq is False and n_eq is False:
        return False
    return None


def pair_verdicts(cand_s: str, peer_s: str, text: str | None, ent: PT.Entailer, params: dict,
                  cache: PairCache | None = None, modes=("ALIGN", "NF-anchored", "EQMV")) -> dict:
    """Pair-level verdicts for canonical strings cand_s, peer_s (peer aligned INTO the candidate's vocabulary).
    Returns {'align_eq', 'nf_eq', 'hyb_eq', 'nf_cost', 'nf_rank', 'nf', 'al', 'secs'}."""
    cache = cache or PairCache(enabled=False)
    t0 = time.time()
    out = {}
    if cand_s == peer_s:
        ident = PT.pair_result(cand_s, peer_s, ent)
        return {"align_eq": True, "nf_eq": True, "hyb_eq": True, "nf_cost": 0.0, "nf_rank": 0, "nf": ident, "al": ident,
                "secs": 0.0}
    for mode in modes:
        if mode == "EQMV":
            a, b = (cand_s, peer_s) if cand_s < peer_s else (peer_s, cand_s)  # symmetric, exp 5 key order
            v = cache.get("EQMV", a, b)
            if v is None:
                from common import eqmv
                res, to = _with_alarm(params["pair_cap_s"], eqmv, PT.parse_fol(a), PT.parse_fol(b))
                v = {"eq": None if (to or res is None) else res[0], "how": None if (to or res is None) else res[1],
                     "timeout": bool(to)}
                cache.put("EQMV", a, b, None, v)
            out["eqmv"] = v
        else:
            v = cache.get(mode, cand_s, peer_s, text)
            if v is None:
                res, to = _with_alarm(params["pair_cap_s"], PT.pair_result, cand_s, peer_s, ent, text=text, variant=mode,
                                      k=params["k"], tau=params["tau"].get(mode))
                v = _slim(_unknown_pair(cand_s, peer_s) if (to or res is None) else res)
                cache.put(mode, cand_s, peer_s, text, v)
            out["nf" if mode == "NF-anchored" else "al"] = v
    a_eq = out.get("eqmv", {}).get("eq")
    n_eq = out.get("nf", {}).get("equiv") if "nf" in out else None
    return {"align_eq": a_eq, "nf_eq": n_eq, "hyb_eq": hyb_of(a_eq, n_eq), "nf_cost": (out.get("nf") or {}).get("cost"),
            "nf_rank": (out.get("nf") or {}).get("rank"), "nf": out.get("nf"), "al": out.get("al"),
            "secs": round(time.time() - t0, 3)}


def composite_record(pv: dict) -> dict:
    """g_score_hyb mapping rule (pre-registered): ALIGN record if align_eq True, else NF record if nf_eq True, else the
    record with more verified unit entailments (ties -> ALIGN)."""
    al, nf = pv["al"], pv["nf"]
    if pv["align_eq"] is True:
        return al
    if pv["nf_eq"] is True:
        return nf
    return al if n_true(al) >= n_true(nf) else nf


# ------------------------------------------------------------------------------------------------ per-sentence worker
def score_sentence(sent: dict, params: dict) -> dict:
    """sent = {'sentence_id', 'text', 'rows': [{'key', 'fol', 'family', 'is_peer', 'pool_rule'?}]}.
    pool_rule: 'lofo' (default: peers of a different family and not the row itself) | 'all' (every peer: PERTURB rows, whose
    base is a reference with no family). Returns {'sentence_id', 'rows': [...], 'pairs': [...], 'stats'}."""
    t_all = time.time()
    text = sent["text"]
    rows = sent["rows"]
    ent = PT.Entailer(params["timeout_ms"])
    cache = PairCache(preload=sent.get("preload"), enabled=params.get("use_cache", True))
    parsed = {}
    for r in rows:
        e = PT.parse_fol(r["fol"])
        parsed[r["key"]] = PT.canon(e) if e is not None else None
    pool = [r for r in rows if r.get("is_peer") and parsed[r["key"]] is not None]
    pool_strings = sorted({parsed[r["key"]] for r in pool})
    cand_strings = sorted({parsed[r["key"]] for r in rows if parsed[r["key"]] is not None})
    PV = {}
    n_to = {"eqmv": 0, "nf": 0, "al": 0}
    for a in sorted(set(cand_strings) | set(pool_strings)):
        for b in pool_strings:
            if a == b:
                continue
            pv = pair_verdicts(a, b, text, ent, params, cache)
            PV[(a, b)] = pv
            n_to["eqmv"] += pv["align_eq"] is None
            n_to["nf"] += bool((pv["nf"] or {}).get("timeout"))
            n_to["al"] += bool((pv["al"] or {}).get("timeout"))
        cache.flush()
    pairs_nf = {k: v["nf"] for k, v in PV.items()}
    pairs_al = {k: v["al"] for k, v in PV.items()}
    pairs_hy = {k: composite_record(v) for k, v in PV.items()}
    out_rows, out_pairs = [], []
    for r in rows:
        cs = parsed[r["key"]]
        o = {"key": r["key"], "coverage_status": "OK" if cs else "UNPARSEABLE"}
        out_rows.append(o)
        if cs is None:
            continue
        if r.get("pool_rule") == "all":
            P_rows = [p for p in pool if p["key"] != r["key"]]
        else:
            P_rows = [p for p in pool if p["family"] != r["family"] and p["key"] != r["key"]]
        P_c = [parsed[p["key"]] for p in P_rows]
        o["n_peers"] = len(P_c)
        o["peer_unavailable"] = len(P_c) < 2
        verd = []
        for p, ps in zip(P_rows, P_c):
            if ps == cs:
                v = {"align_eq": True, "nf_eq": True, "hyb_eq": True, "nf_cost": 0.0}
            else:
                pv = PV[(cs, ps)]
                v = {k: pv[k] for k in ("align_eq", "nf_eq", "hyb_eq", "nf_cost")}
            verd.append(v)
            if params.get("emit_pairs", True):
                out_pairs.append({"cand": r["key"], "peer": p["key"], **v})
        if len(P_c) < 2:
            for c in ("c_align", "c_nf", "c_hyb", "g_align", "g_nf", "g_hyb"):
                o[c] = None
            o["n_unknown_hyb"] = 0
            continue
        n = len(P_c)
        o["c_align"] = 1 - sum(v["align_eq"] is True for v in verd) / n
        o["c_hyb"] = 1 - sum(v["hyb_eq"] is True for v in verd) / n
        o["c_nf_pairs"] = 1 - sum(v["nf_eq"] is True for v in verd) / n
        o["n_agree_align"] = sum(v["align_eq"] is True for v in verd)
        o["n_agree_nf"] = sum(v["nf_eq"] is True for v in verd)
        o["n_agree_hyb"] = sum(v["hyb_eq"] is True for v in verd)
        o["n_unknown_align"] = sum(v["align_eq"] is None for v in verd)
        o["n_unknown_nf"] = sum(v["nf_eq"] is None for v in verd)
        o["n_unknown_hyb"] = sum(v["hyb_eq"] is None for v in verd)
        for tag, pr in (("nf", pairs_nf), ("align", pairs_al), ("hyb", pairs_hy)):
            try:
                gc_ = PT.graded_consensus(cs, P_c, pr, ent, return_codes=params.get("codes", False))
            except (KeyError, RecursionError) as ex:  # noqa: PERF203 - recorded, never silently dropped
                o[f"g_{tag}"] = None
                o[f"g_{tag}_err"] = str(ex)[:120]
                continue
            o[f"g_{tag}"] = gc_["g_score"]
            if tag == "nf":
                o["c_nf"] = gc_["c_score_nf"]
            if tag == "align":
                o["c_align_graded_map"] = gc_["c_score_nf"]  # exp 5 frozen 'c_score_nf' column (ALIGN-variant equivalence)
            if params.get("codes", False):
                o[f"top_code_{tag}"] = gc_.get("top_code")
                o[f"unit_codes_{tag}"] = [c["code"] for c in gc_.get("unit_codes", [])]
        # medoid under the HYB agreement (for Part C typing)
        if params.get("medoid", False):
            for md in ("hyb_eq", "nf_eq", "align_eq"):
                o["medoid_" + md.split("_")[0]] = medoid_of(P_c, PV, md)
    stats = {"n_pairs": len(PV), "timeouts": n_to, "secs_total": round(time.time() - t_all, 2), "ent": dict(ent.stats),
             "n_cache_hits_preload": len(sent.get("preload") or {}), "n_new_cache": len(cache.new)}
    return {"sentence_id": sent["sentence_id"], "rows": out_rows, "pairs": out_pairs, "stats": stats, "new_cache": cache.new}


def medoid_of(P: list[str], PV: dict, mode: str = "hyb_eq") -> str | None:
    """Pool member agreeing (under `mode`) with the most other pool members (ties -> lexicographically first string)."""
    if not P:
        return None
    best = None
    for i, a in enumerate(P):
        n = sum(1 for j, b in enumerate(P) if j != i and (a == b or (PV.get((a, b)) or {}).get(mode) is True))
        if best is None or n > best[0] or (n == best[0] and a < best[1]):
            best = (n, a)
    return best[1]

source_files.vendor_x8/peer_text.py:
"""PEER+TEXT: gold-free faithfulness scoring of an NL->FOL candidate from (text, fol, peer formalisations).

PEER side (text-free, name-free, graded cross-family consensus):
  parse_fol(s)                      dataset-E parser (vendor_e/fol.py) -> AST or None (coverage failure, counted).
  claim_units(ast)                  the formula as a list of independent closed claims (conjunction of units == formula).
  symbol_signature(ast)             per predicate/constant a NAME-FREE structural signature (arity, polarity profile,
                                    quantifier force / block of its argument variables, 1-WL neighbourhood hash).
  name_free_align(cand, peer, ...)  k-best predicate/constant bijections peer->candidate from signatures only (NF-pure)
                                    or signatures + text anchors (NF-anchored), verified by unit entailment.
  entails(premise, unit)            finite-model refuter (64 random interpretations, domains 1..3) then z3.
  graded_consensus(...)             support (share of candidate claims the peers entail), coverage (share of the peers'
                                    majority claims the candidate entails), g_score = 1 - F1(support, coverage),
                                    c_score_nf = 1 - share of peers z3-equivalent under the accepted mapping,
                                    unit_codes: NEG / QUANT / SWAP / ADD for unsupported claims, DROP for uncovered ones.
TEXT side (vendored unchanged from iteration-1 exp A, fol_triage.py):
  l2_bow(text, fol)                 content accounting: #unanchored predicates + share of uncarried content words.
  l3_z3(q, fol)                     role questionnaire of the TEXT (small LLM, never sees the formula) vs the formula's
                                    exact z3 role profile; sum of the 5 gated field mismatches.
FUSION:
  peer_text_score(text, fol, peers, frozen)  frozen logistic over [g_score, c_score_nf, l2_bow, l3_z3].

What PEER is blind to (stated, measured): errors every peer shares (peer-endorsed errors), meaning-level renames that
keep structure (MEANING_RENAME: a wrong predicate in the right place), and for NF-pure errors that are automorphisms of the
formula structure (e.g. ∀x(B→A) vs ∀x(A→B) with A, B structurally symmetric: the ROLE_PERMUTE probe).
What TEXT is blind to: structure the text words do not reveal (scope, binding), and anything the small LLM misreads.
"""
from __future__ import annotations

import hashlib
import itertools
import math
import os
import re
import sys
import time
from functools import lru_cache
from pathlib import Path

import numpy as np
import z3
from scipy.optimize import linear_sum_assignment

sys.setrecursionlimit(20000)
SRC = Path(__file__).resolve().parent
ROOT = SRC.parent
os.environ.setdefault("NLTK_DATA", str(ROOT / "data" / "nltk_data"))
if str(SRC) not in sys.path:
    sys.path.insert(0, str(SRC))
import vendor_e.fol as EFOL  # noqa: E402  (the parser that produced dataset E's UNPARSEABLE labels)

# every vendored module does `from fol import ...`: bind that name to the dataset-E parser (fixed <-> / ⊕ precedence)
sys.modules["fol"] = EFOL
for _p in (SRC / "vendor_c", SRC / "vendor_a"):
    if str(_p) not in sys.path:
        sys.path.insert(1, str(_p))

BINSYM = {"iff": "↔", "xor": "⊕", "imp": "→", "or": "∨", "and": "∧"}
BIN = ("and", "or", "imp", "iff", "xor")
UNIT_CAP = 16


# =================================================================================================== parse & print
def parse_fol(s: str | None):
    """Dataset-E parser. Returns the AST or None (unparseable = coverage failure, never silently dropped)."""
    if s is None or not str(s).strip():
        return None
    try:
        return EFOL.parse(str(s))
    except (ValueError, IndexError, RecursionError, TypeError):
        return None


def to_str(e) -> str:
    """Fully parenthesised Unicode rendering; parse_fol(to_str(e)) == e."""
    k = e[0]
    if k == "atom":
        return f"{e[1]}({', '.join(e[2])})" if e[2] else e[1]
    if k in ("all", "ex"):
        return f"{'∀' if k == 'all' else '∃'}{e[1]} ({to_str(e[2])})"
    if k == "not":
        return f"¬({to_str(e[1])})" if e[1][0] not in ("atom", "not") else f"¬{to_str(e[1])}"
    return f"({to_str(e[1])} {BINSYM[k]} {to_str(e[2])})"


def free_vars(e, bound=frozenset()) -> set:
    k = e[0]
    if k == "atom":
        return set()  # arguments not bound are constants in this grammar
    if k in ("all", "ex"):
        return free_vars(e[2], bound | {e[1]})
    if k == "not":
        return free_vars(e[1], bound)
    return free_vars(e[1], bound) | free_vars(e[2], bound)


def mentions(e, v: str) -> bool:
    k = e[0]
    if k == "atom":
        return v in e[2]
    if k in ("all", "ex"):
        return False if e[1] == v else mentions(e[2], v)
    if k == "not":
        return mentions(e[1], v)
    return mentions(e[1], v) or mentions(e[2], v)


def alpha(e, env=None, ctr=None):
    """Alpha-normalise bound variables to v0, v1, ... in order of their binders (canonical strings; unique binders)."""
    env = {} if env is None else env
    ctr = [0] if ctr is None else ctr
    k = e[0]
    if k == "atom":
        return ("atom", e[1], tuple(env.get(a, a) for a in e[2]))
    if k in ("all", "ex"):
        nv = f"v{ctr[0]}"
        ctr[0] += 1
        return (k, nv, alpha(e[2], {**env, e[1]: nv}, ctr))
    if k == "not":
        return ("not", alpha(e[1], env, ctr))
    return (k, alpha(e[1], env, ctr), alpha(e[2], env, ctr))


def canon(e) -> str:
    return to_str(alpha(e))


def pred_keys(e, acc=None) -> dict:
    """{(name, arity): True} in order of first occurrence."""
    acc = {} if acc is None else acc
    k = e[0]
    if k == "atom":
        acc.setdefault((e[1], len(e[2])), True)
    elif k in ("all", "ex"):
        pred_keys(e[2], acc)
    elif k == "not":
        pred_keys(e[1], acc)
    else:
        pred_keys(e[1], acc)
        pred_keys(e[2], acc)
    return acc


def constants(e, bound=frozenset(), acc=None) -> dict:
    acc = {} if acc is None else acc
    k = e[0]
    if k == "atom":
        for a in e[2]:
            if a not in bound:
                acc.setdefault(a, True)
    elif k in ("all", "ex"):
        constants(e[2], bound | {e[1]}, acc)
    elif k == "not":
        constants(e[1], bound, acc)
    else:
        constants(e[1], bound, acc)
        constants(e[2], bound, acc)
    return acc


def rename(e, pmap: dict, cmap: dict, bound=frozenset()):
    """pmap: {(name, arity): new_name}; cmap: {const: new_const}. Bound variables untouched."""
    k = e[0]
    if k == "atom":
        return ("atom", pmap.get((e[1], len(e[2])), e[1]), tuple(a if a in bound else cmap.get(a, a) for a in e[2]))
    if k in ("all", "ex"):
        return (k, e[1], rename(e[2], pmap, cmap, bound | {e[1]}))
    if k == "not":
        return ("not", rename(e[1], pmap, cmap, bound))
    return (k, rename(e[1], pmap, cmap, bound), rename(e[2], pmap, cmap, bound))


# =================================================================================================== claim units
def _conseq_pieces(c) -> list:
    """C == AND(pieces). Splits ∧, curried →, ∀ over ∧, ¬∨ (De Morgan)."""
    k = c[0]
    if k == "and":
        return _conseq_pieces(c[1]) + _conseq_pieces(c[2])
    if k == "imp":
        return [("imp", c[1], p) for p in _conseq_pieces(c[2])]
    if k == "all":
        return [("all", c[1], p) if mentions(p, c[1]) else p for p in _conseq_pieces(c[2])]
    if k == "not" and c[1][0] == "or":
        return _conseq_pieces(("not", c[1][1])) + _conseq_pieces(("not", c[1][2]))
    if k == "not" and c[1][0] == "not":
        return _conseq_pieces(c[1][1])
    return [c]


def claim_units(e, cap: int = UNIT_CAP) -> tuple[list, list, bool]:
    """-> (units, locations, truncated). The formula is logically equivalent to the conjunction of its units
    (before truncation): top-level ∧ split; ∀ distributed over ∧; for a universal rule ∀x̄(R → C1 ∧ .. ∧ Cm) one unit
    ∀x̄(R → Cj) per consequent conjunct; ¬¬, ¬(A∨B), ¬(A→B), ¬∃ normalised so that they split; ∃-claims kept whole;
    ground literals are units. Units keep the index path of their origin (for DROP/ADD location reports).
    Vacuous quantifiers are removed from units. Cap: first `cap` units in textual order (truncated=True if cut)."""
    out, locs = [], []

    def emit(prefix, x, loc):
        for v in reversed(prefix):
            if mentions(x, v):
                x = ("all", v, x)
        out.append(x)
        locs.append(loc)

    def split(x, prefix, loc):
        k = x[0]
        if k == "and":
            split(x[1], prefix, loc + (1,))
            split(x[2], prefix, loc + (2,))
            return
        if k == "all":
            split(x[2], prefix + [x[1]], loc + (2,))
            return
        if k == "not":
            y = x[1]
            if y[0] == "not":
                return split(y[1], prefix, loc + (1,))
            if y[0] == "or":
                return split(("and", ("not", y[1]), ("not", y[2])), prefix, loc)
            if y[0] == "imp":
                return split(("and", y[1], ("not", y[2])), prefix, loc)
            if y[0] == "ex":
                return split(("all", y[1], ("not", y[2])), prefix, loc)
        if k == "imp":
            ps = _conseq_pieces(x[2])
            for i, c in enumerate(ps):
                emit(prefix, ("imp", x[1], c), loc + (2, i) if len(ps) > 1 else loc)
            return
        emit(prefix, x, loc)

    split(e, [], ())
    trunc = len(out) > cap
    return out[:cap], locs[:cap], trunc


@lru_cache(maxsize=200000)
def units_of(s: str):
    """Cached claim units of a canonical formula string -> (tuple(unit canon strings), tuple(unit ASTs), truncated)."""
    e = parse_fol(s)
    us, _, tr = claim_units(e)
    us = [alpha(u) for u in us]
    return tuple(to_str(u) for u in us), tuple(us), tr


# =================================================================================================== signatures
def _occurrences(e):
    """Atom occurrences with syntactic polarity (+1 up, -1 down, 0 mixed under ↔/⊕) and argument binders."""
    occ = []

    def go(x, pol, binders, depth):
        k = x[0]
        if k == "atom":
            occ.append((x[1], len(x[2]), x[2], pol, dict(binders)))
        elif k in ("all", "ex"):
            go(x[2], pol, {**binders, x[1]: (k, depth)}, depth + 1)
        elif k == "not":
            go(x[1], -pol, binders, depth)
        elif k == "imp":
            go(x[1], -pol, binders, depth)
            go(x[2], pol, binders, depth)
        elif k in ("iff", "xor"):
            go(x[1], 0, binders, depth)
            go(x[2], 0, binders, depth)
        else:
            go(x[1], pol, binders, depth)
            go(x[2], pol, binders, depth)
    go(alpha(e), 1, {}, 0)
    return occ


def _qdepth(e) -> int:
    k = e[0]
    if k == "atom":
        return 0
    if k in ("all", "ex"):
        return 1 + _qdepth(e[2])
    if k == "not":
        return _qdepth(e[1])
    return max(_qdepth(e[1]), _qdepth(e[2]))


CLAMP_DOMAINS = ((1, 64), (2, 64))


def clamp_profile(e) -> dict:
    """Rewrite-invariant SEMANTIC signature: for every predicate P, the truth rate of the formula over 128 random finite
    interpretations (domains 1 and 2) with P clamped to all-true and to all-false. Logically equivalent formulas
    (contrapositive, De Morgan, prenex, reordering) get identical profiles up to sampling of the other predicates."""
    ea = alpha(e)
    out = {}
    for key in pred_keys(ea):
        vals = []
        for val in (True, False):
            tot = n = 0
            for d, m in CLAMP_DOMAINS:
                v = _fm_eval(ea, d, m, clamp=(key[0], key[1], val))
                if v is not None:
                    tot += int(v.sum())
                    n += len(v)
            vals.append(tot / n if n else 0.5)
        out[key] = tuple(vals)
    return out


def symbol_signature(e) -> dict:
    """NAME-FREE signature of every predicate and constant of formula e.
    pred (name, arity) -> {'arity', 'pol': (up, down, mixed) shares over occurrences (syntactic polarity; ↔/⊕ operands
    are MIXED; syntactic monotonicity is sound for semantic monotonicity), 'qforce': mean over argument slots of 1 (∀) /
    0 (∃) / 0.5 (constant), 'qblock': mean binder depth / max quantifier depth, 'nbr': set of (arity, polarity, own slot,
    other slot) of atoms sharing a bound variable with it (1-WL neighbourhood)}.
    const -> {'fill': set of (arity, slot, polarity) it fills}."""
    occ = _occurrences(e)
    md = max(1, _qdepth(e))
    P, C = {}, {}
    for i, (name, ar, args, pol, b) in enumerate(occ):
        d = P.setdefault((name, ar), {"arity": ar, "pc": [0, 0, 0], "qf": [], "qb": [], "nbr": set()})
        d["pc"][0 if pol > 0 else (1 if pol < 0 else 2)] += 1
        for s, a in enumerate(args):
            if a in b:
                d["qf"].append(1.0 if b[a][0] == "all" else 0.0)
                d["qb"].append(b[a][1] / md)
            else:
                d["qf"].append(0.5)
                d["qb"].append(0.0)
                C.setdefault(a, set()).add((ar, s, pol))
        for j, (n2, ar2, args2, pol2, b2) in enumerate(occ):
            if j == i:
                continue
            for s, a in enumerate(args):
                if a in b:
                    for s2, a2 in enumerate(args2):
                        if a2 == a and b2.get(a2) == b[a]:
                            d["nbr"].add((ar2, pol2, s, s2))
    out = {}
    cp = clamp_profile(e)
    for k, d in P.items():
        n = sum(d["pc"])
        out[k] = {"arity": d["arity"], "pol": tuple(x / n for x in d["pc"]), "clamp": cp.get(k, (0.5, 0.5)),
                  "qforce": float(np.mean(d["qf"])) if d["qf"] else 0.5,
                  "qblock": float(np.mean(d["qb"])) if d["qb"] else 0.0, "nbr": frozenset(d["nbr"])}
    return {"preds": out, "consts": {c: {"fill": frozenset(v)} for c, v in C.items()}}


def _jac(a, b) -> float:
    if not a and not b:
        return 1.0
    return len(a & b) / len(a | b)


def pred_cost(a: dict, b: dict) -> float:
    """Structural cost in [0,1]; five components weighted 0.2 each, fixed a priori (not tuned): polarity profile L1/2,
    quantifier force, quantifier block, 1 - Jaccard(neighbourhood), semantic clamp profile mean |difference|."""
    l1 = sum(abs(x - y) for x, y in zip(a["pol"], b["pol"])) / 2
    cl = (abs(a["clamp"][0] - b["clamp"][0]) + abs(a["clamp"][1] - b["clamp"][1])) / 2
    return 0.2 * l1 + 0.2 * abs(a["qforce"] - b["qforce"]) + 0.2 * abs(a["qblock"] - b["qblock"]) + \
        0.2 * (1 - _jac(a["nbr"], b["nbr"])) + 0.2 * cl


# ------------------------------------------------------------------------------------------- text anchors
_TEXT_TOK = re.compile(r"[A-Za-z]+|\d+")


@lru_cache(maxsize=100000)
def _text_tokens(text: str) -> tuple:
    import content_accounting as ca  # vendor_a
    return tuple((i, w.lower()) for i, w in enumerate(_TEXT_TOK.findall(text))
                 if w.lower() not in ca.FUNC and len(w) > 1)


@lru_cache(maxsize=200000)
def text_anchor(symbol: str, text: str) -> frozenset:
    """Sentence token indices matched by the words of a predicate/constant name (exp A word_match: Porter stem or
    WordNet lemma / synonym / derivation). Used ONLY by NF-anchored."""
    import fol_triage as FT  # vendor_a
    nw = FT.name_words(symbol)
    toks = _text_tokens(text)
    return frozenset(i for i, w in toks for x in nw if FT.word_match(w, x))


def anchor_cost(a: frozenset, b: frozenset) -> float:
    if not a or not b:
        return 0.5
    return 1 - len(a & b) / len(a | b)


# =================================================================================================== alignment
BIG = 1e6
DUMMY = 0.6


def _solve(M: np.ndarray):
    r, c = linear_sum_assignment(M)
    return r, c, float(M[r, c].sum())


def name_free_align(cand, peer, text: str | None = None, variant: str = "NF-pure", k: int = 5,
                    sig_c: dict | None = None, sig_p: dict | None = None) -> list[dict]:
    """k cheapest peer->candidate symbol bijections (predicates within equal arity; constants separately; arity mismatch =
    +inf; unmatched symbols pay DUMMY=0.6 and stay fresh 'pp_' symbols). k-best by Murty's algorithm. NF-anchored adds 1.0 x anchor cost (1 - Jaccard of text anchors, 0.5 if either side is
    unanchored). Returns [{'pmap', 'cmap', 'cost'}] sorted by cost (total over symbols)."""
    sig_c = sig_c or symbol_signature(cand)
    sig_p = sig_p or symbol_signature(peer)
    Pp, Pc = list(sig_p["preds"]), list(sig_c["preds"])
    Kp, Kc = list(sig_p["consts"]), list(sig_c["consts"])
    rows = [("p", x) for x in Pp] + [("c", x) for x in Kp]
    cols = [("p", x) for x in Pc] + [("c", x) for x in Kc]
    nr, nc = len(rows), len(cols)
    n = nr + nc
    M = np.full((n, n), BIG)
    M[nr:, nc:] = 0.0
    anch = variant == "NF-anchored" and text
    for i, (si, x) in enumerate(rows):
        M[i, nc + i] = DUMMY
        for j, (sj, y) in enumerate(cols):
            if si != sj:
                continue
            if si == "p":
                if x[1] != y[1]:
                    continue
                cst = pred_cost(sig_p["preds"][x], sig_c["preds"][y])
            else:
                cst = 1 - _jac(sig_p["consts"][x]["fill"], sig_c["consts"][y]["fill"])
            if anch:  # both anchored: the text decides, structure breaks ties; else structure + 0.5 (pre-registered)
                ax_, ay_ = text_anchor(x[0] if si == "p" else x, text), text_anchor(y[0] if sj == "p" else y, text)
                cst = (anchor_cost(ax_, ay_) + 0.25 * cst) if (ax_ and ay_) else (cst + 0.5)
            M[i, j] = cst
    for j in range(nc):
        M[nr + j, j] = DUMMY

    def to_map(r, c):
        pmap, cmap = {}, {}
        for i, j in zip(r, c):
            if i >= nr:
                continue
            si, x = rows[i]
            if j < nc:
                y = cols[j][1]
                if si == "p":
                    pmap[x] = y[0]
                else:
                    cmap[x] = y
            else:
                if si == "p":
                    pmap[x] = "pp_" + x[0]
                else:
                    cmap[x] = "pp_" + x
        return pmap, cmap

    if n == 0:
        return [{"pmap": {}, "cmap": {}, "cost": 0.0}]
    return [{"pmap": pm, "cmap": cm, "cost": t} for (pm, cm), t in _murty(M, nr, k, to_map)]


def _murty(M: np.ndarray, nr: int, k: int, to_map) -> list:
    """Murty's k-best assignment, partitioning on the peer-row edges (they determine the mapping)."""
    import heapq

    def solve(forced, forbidden):
        M2 = M.copy()
        for (i, j) in forbidden:
            M2[i, j] = BIG
        for (i, j) in forced:
            keep = M2[i, j]
            M2[i, :] = BIG
            M2[:, j] = BIG
            M2[i, j] = keep
        r, c, t = _solve(M2)
        if t >= BIG / 2:
            return None
        return r, c, t
    first = solve((), ())
    if first is None:
        return []
    heap = [(first[2], 0, first, (), ())]
    ctr, out, seen = 1, [], set()
    while heap and len(out) < k:
        t, _, (r, c, _t), forced, forbidden = heapq.heappop(heap)
        mp = to_map(r, c)
        key = repr(sorted(mp[0].items()) + sorted(mp[1].items()))
        if key not in seen:
            seen.add(key)
            out.append((mp, t))
        edges = [(i, j) for i, j in zip(r, c) if i < nr and (i, j) not in forced]
        f = list(forced)
        for e in edges:
            sol = solve(tuple(f), forbidden + (e,))
            if sol is not None:
                heapq.heappush(heap, (sol[2], ctr, sol, tuple(f), forbidden + (e,)))
                ctr += 1
            f.append(e)
        if len(heap) > 50 * k:
            heap = heapq.nsmallest(10 * k, heap)
            heapq.heapify(heap)
    return out


# =================================================================================================== entailment
FM_DOMAINS = ((1, 16), (2, 24), (3, 24))          # (domain size, #random interpretations) -> 64 models
FM_P = np.array([0.15, 0.5, 0.85])


def _seed(*parts) -> int:
    return int(hashlib.sha1("|".join(map(str, parts)).encode()).hexdigest()[:12], 16)


@lru_cache(maxsize=100000)
def _table(name: str, arity: int, d: int, m: int) -> np.ndarray:
    rng = np.random.default_rng(_seed("P", name, arity, d, m))
    p = FM_P[np.arange(m) % 3].reshape((m,) + (1,) * arity)
    return rng.random((m,) + (d,) * arity) < p


@lru_cache(maxsize=100000)
def _const(name: str, d: int, m: int) -> np.ndarray:
    rng = np.random.default_rng(_seed("C", name, d, m))
    return rng.integers(0, d, size=m)


def _fm_eval(e, d: int, m: int, clamp: tuple | None = None) -> np.ndarray | None:
    """Truth value of closed formula e in m random interpretations over a domain of size d -> bool array (m,).
    Variables are array axes; quantifiers reduce over their axis. None if too many variables for this domain."""
    ea = alpha(e)
    nv = sum(1 for _ in _binders(ea))
    if d ** nv * m > 2_000_000:
        return None
    nd = 1 + nv
    ax = {}

    def shape_at(i):
        s = [1] * nd
        s[i] = -1
        return s
    mid = np.arange(m).reshape(shape_at(0))

    def ev(x):
        k = x[0]
        if k == "atom":
            if clamp is not None and clamp[0] == x[1] and clamp[1] == len(x[2]):
                return np.full((m,) + (1,) * nv, clamp[2])
            T = _table(x[1], len(x[2]), d, m)
            if not x[2]:
                return T.reshape(shape_at(0))
            idx = [mid]
            for a in x[2]:
                if a in ax:
                    idx.append(np.arange(d).reshape(shape_at(ax[a])))
                else:
                    idx.append(_const(a, d, m).reshape(shape_at(0)))
            return T[tuple(idx)]
        if k in ("all", "ex"):
            ax[x[1]] = 1 + int(x[1][1:])
            b = ev(x[2])
            if b.ndim < nd:
                b = b.reshape(b.shape + (1,) * (nd - b.ndim))
            return b.all(axis=ax[x[1]], keepdims=True) if k == "all" else b.any(axis=ax[x[1]], keepdims=True)
        if k == "not":
            return ~ev(x[1])
        a, b = ev(x[1]), ev(x[2])
        if k == "and":
            return a & b
        if k == "or":
            return a | b
        if k == "imp":
            return ~a | b
        if k == "iff":
            return a == b
        return a ^ b
    r = ev(ea)
    return np.broadcast_to(r, (m,) + (1,) * (r.ndim - 1)).reshape(m)


def _binders(e):
    k = e[0]
    if k in ("all", "ex"):
        yield e[1]
        yield from _binders(e[2])
    elif k == "not":
        yield from _binders(e[1])
    elif k != "atom":
        yield from _binders(e[1])
        yield from _binders(e[2])


_FM_CACHE: dict = {}


def fm_vector(s: str, e=None) -> list:
    """Cached truth vectors of formula string s over the fixed random interpretations (one array per domain)."""
    r = _FM_CACHE.get(s)
    if r is None:
        e = e if e is not None else parse_fol(s)
        r = [_fm_eval(e, d, m) for d, m in FM_DOMAINS]
        if len(_FM_CACHE) > 300000:
            _FM_CACHE.clear()
        _FM_CACHE[s] = r
    return r


def fm_refutes(prem_s: str, unit_s: str, prem=None, unit=None) -> bool:
    """True iff some random finite interpretation makes the premise true and the unit false (a genuine countermodel,
    so prem ⊭ unit). Sound: never True when prem ⊨ unit."""
    vp, vu = fm_vector(prem_s, prem), fm_vector(unit_s, unit)
    for a, b in zip(vp, vu):
        if a is not None and b is not None and bool(np.any(a & ~b)):
            return True
    return False


def z3_entails(prem, unit, ms: int = 2000):
    """z3: prem ∧ ¬unit unsat -> True; sat -> False; unknown/timeout -> None."""
    P = {}
    for key in list(pred_keys(prem)) + list(pred_keys(unit)):
        q = f"{key[0]}/{key[1]}"
        if q not in P:
            P[q] = EFOL.mkpred(q, key[1])
    s = z3.Solver()
    s.set("timeout", ms)
    s.add(EFOL.to_z3(prem, {}, P))
    s.add(z3.Not(EFOL.to_z3(unit, {}, P)))
    r = s.check()
    return True if r == z3.unsat else (False if r == z3.sat else None)


class Entailer:
    """entails(premise, unit) with a per-process cache keyed by canonical strings.
    Order: identical -> True; unit is literally one of the premise's claim units -> True; finite-model countermodel ->
    False; z3 (timeout_ms) -> True / False / None (UNKNOWN, never counted as False)."""

    def __init__(self, timeout_ms: int = 2000, use_fm: bool = True):
        self.ms = timeout_ms
        self.use_fm = use_fm
        self.cache: dict = {}
        self.stats = {"identical": 0, "unit": 0, "fm": 0, "z3_true": 0, "z3_false": 0, "z3_unknown": 0, "cached": 0}

    def __call__(self, prem_s: str, unit_s: str, prem=None, unit=None):
        key = (prem_s, unit_s)
        if key in self.cache:
            self.stats["cached"] += 1
            return self.cache[key]
        if prem_s == unit_s:
            r = True
            self.stats["identical"] += 1
        elif unit_s in units_of(prem_s)[0]:
            r = True
            self.stats["unit"] += 1
        elif self.use_fm and fm_refutes(prem_s, unit_s, prem, unit):
            r = False
            self.stats["fm"] += 1
        else:
            prem = prem if prem is not None else parse_fol(prem_s)
            unit = unit if unit is not None else parse_fol(unit_s)
            try:
                r = z3_entails(prem, unit, self.ms)
            except (z3.Z3Exception, RecursionError, KeyError) as ex:  # noqa: F841
                r = None
            self.stats["z3_true" if r is True else ("z3_false" if r is False else "z3_unknown")] += 1
        if len(self.cache) > 500000:
            self.cache.clear()
        self.cache[key] = r
        return r


# =================================================================================================== pair results
def pair_result(cand_s: str, peer_s: str, ent: Entailer, text: str | None = None, variant: str = "NF-pure",
                k: int = 5, tau: float | None = None, select_by: str = "fm") -> dict:
    """Align peer into the candidate's vocabulary and verify unit entailments in both directions.
    cand_s/peer_s are canonical strings. Mapping acceptance: among the k-best mappings with cost <= min_cost + tau
    (tau = inf for NF-pure), take the one with the most unit entailments not refuted by the finite-model refuter
    (select_by='fm', a sound upper bound on the z3-verified count; 'z3' uses full entailment), ties -> lower cost.
    Returns {'fwd': [peer ⊨ cand-unit], 'bwd': [cand ⊨ peer-unit], 'peer_r': renamed peer string,
             'peer_units_r': renamed peer unit strings, 'equiv', 'cost', 'n_maps', 'rank'}."""
    cu_s, cu, ctr = units_of(cand_s)
    pu_s, pu, ptr = units_of(peer_s)
    if cand_s == peer_s:
        return {"fwd": [True] * len(cu_s), "bwd": [True] * len(pu_s), "peer_r": cand_s, "peer_units_r": list(pu_s),
                "equiv": True, "cost": 0.0, "n_maps": 0, "rank": 0}
    ce, pe = parse_fol(cand_s), parse_fol(peer_s)
    if variant == "ALIGN":  # iteration-1 aligner (name similarity, repair_census.align): one mapping peer -> candidate
        from repair_census import align as _rc_align
        _, pmap, cmap = _rc_align(pe, ce)
        maps = [{"pmap": dict(pmap), "cmap": dict(cmap), "cost": 0.0}]
    else:
        maps = name_free_align(ce, pe, text=text, variant=variant, k=k)
    tau = math.inf if tau is None else tau
    lo = maps[0]["cost"]
    window = [m for m in maps if m["cost"] <= lo + tau + 1e-9]
    best, best_key, best_rank = None, None, 0
    for rank, m in enumerate(window):
        pr = rename(pe, m["pmap"], m["cmap"])
        pr_s = canon(pr)
        pur = [canon(rename(u, m["pmap"], m["cmap"])) for u in pu]
        if select_by == "fm":
            n_ok = sum(not fm_refutes(pr_s, u) for u in cu_s) + sum(not fm_refutes(cand_s, v) for v in pur)
        else:
            n_ok = sum(ent(pr_s, u) is True for u in cu_s) + sum(ent(cand_s, v) is True for v in pur)
        key = (n_ok, -m["cost"])
        if best_key is None or key > best_key:
            best, best_key, best_rank = (m, pr_s, pur), key, rank
    m, pr_s, pur = best
    fwd = [ent(pr_s, u) for u in cu_s]
    bwd = [ent(cand_s, v) for v in pur]
    if not ctr and not ptr:
        equiv = True if (all(x is True for x in fwd) and all(x is True for x in bwd)) else \
            (None if any(x is None for x in fwd + bwd) and not any(x is False for x in fwd + bwd) else False)
    else:
        a, b = ent(pr_s, cand_s), ent(cand_s, pr_s)
        equiv = True if (a is True and b is True) else (False if (a is False or b is False) else None)
    return {"fwd": fwd, "bwd": bwd, "peer_r": pr_s, "peer_units_r": pur, "equiv": equiv, "cost": m["cost"],
            "n_maps": len(maps), "rank": best_rank}


# =================================================================================================== graded consensus
def _variants_quant(u):
    """one ∀<->∃ flip of u (each quantifier node, max 4)."""
    out = []

    def go(x, path):
        k = x[0]
        if k in ("all", "ex"):
            out.append(path)
            go(x[2], path + (2,))
        elif k == "not":
            go(x[1], path + (1,))
        elif k != "atom":
            go(x[1], path + (1,))
            go(x[2], path + (2,))
    go(u, ())
    res = []
    for p in out[:4]:
        res.append(_replace(u, p, lambda n: ("ex" if n[0] == "all" else "all", n[1], n[2])))
    return res


def _variants_swap(u):
    out = []

    def go(x, path):
        k = x[0]
        if k == "atom":
            if len(x[2]) == 2 and x[2][0] != x[2][1]:
                out.append(path)
        elif k in ("all", "ex"):
            go(x[2], path + (2,))
        elif k == "not":
            go(x[1], path + (1,))
        else:
            go(x[1], path + (1,))
            go(x[2], path + (2,))
    go(u, ())
    return [_replace(u, p, lambda n: ("atom", n[1], (n[2][1], n[2][0]))) for p in out[:4]]


def _variants_neg(u):
    """one literal polarity toggle of u (¬ added to / removed from one atom occurrence, max 6)."""
    out = []

    def go(x, path):
        k = x[0]
        if k == "atom":
            out.append((path, "add"))
        elif k == "not" and x[1][0] == "atom":
            out.append((path, "del"))
        elif k in ("all", "ex"):
            go(x[2], path + (2,))
        elif k == "not":
            go(x[1], path + (1,))
        else:
            go(x[1], path + (1,))
            go(x[2], path + (2,))
    go(u, ())
    return [_replace(u, p, (lambda n: ("not", n)) if how == "add" else (lambda n: n[1])) for p, how in out[:6]]


def _replace(e, path, fn):
    if not path:
        return fn(e)
    lst = list(e)
    lst[path[0]] = _replace(e[path[0]], path[1:], fn)
    return tuple(lst)


CODE_PRIORITY = ["NEG", "QUANT", "SWAP", "DROP", "ADD"]


def _majority_support(ent: Entailer, peers_r: list[str], u_s: str) -> bool:
    """True iff >= 50% of the (renamed) peers entail u (UNKNOWN pairs excluded); early exit."""
    yes = no = 0
    n = len(peers_r)
    for i, p in enumerate(peers_r):
        r = ent(p, u_s)
        if r is True:
            yes += 1
        elif r is False:
            no += 1
        if no > n / 2:
            return False
        if yes >= n / 2 and yes > 0:
            return True
    tot = yes + no
    return tot > 0 and yes / tot >= 0.5


def graded_consensus(cand_s: str, pool: list[str], pairs: dict, ent: Entailer, return_codes: bool = True,
                     unit_locs: bool = True) -> dict:
    """Graded, name-free consensus of candidate formula cand_s (canonical string) against its peer pool.

    pool   : canonical strings of the peers (already leave-one-family-out filtered; duplicates allowed = one vote each).
    pairs  : {(a, b): pair_result(a, b)} for a in {cand} ∪ pool, b in pool, a != b (b aligned INTO a's vocabulary).
    support  = mean over candidate units u (units UNKNOWN for all peers excluded) of the share of peers p with σ_p(p) ⊨ u.
    coverage = mean over peers p of the share of p's MAJORITY units (entailed by >= 50% of the other pool peers) that
               the candidate entails (σ_p applied). A peer without majority units is skipped; no majority units at all
               -> coverage = 1 (nothing agreed to cover).
    g_score  = 1 - 2·support·coverage / (support + coverage)  (1 if both 0); higher = more likely an error.
    c_score_nf = 1 - share of peers z3-equivalent to the candidate under the accepted mapping.
    unit_codes: unsupported unit (support < 0.5) -> NEG if one literal-polarity toggle of u has majority support, else QUANT if one ∀/∃ flip of u
                has it, else SWAP if one binary-argument swap of u has it, else ADD; an uncovered majority unit -> DROP.
    Blind to: errors shared by the majority of peers; meaning renames with unchanged structure."""
    cu_s, cu, ctr = units_of(cand_s)
    n_peers = len(pool)
    out = {"n_units": len(cu_s), "units_truncated": ctr, "n_peers_used": n_peers}
    if n_peers < 2:
        out.update(g_score=None, support=None, coverage=None, c_score_nf=None, peer_unavailable=True, unit_codes=[],
                   n_unknown=0)
        return out
    res = [pairs[(cand_s, p)] if p != cand_s else None for p in pool]

    def fwd_of(i, r):
        return True if r is None else r["fwd"][i]
    fracs, n_unknown, unit_support = [], 0, []
    for i in range(len(cu_s)):
        vals = [fwd_of(i, r) for r in res]
        n_unknown += sum(v is None for v in vals)
        vv = [v for v in vals if v is not None]
        if vv:
            f = sum(vv) / len(vv)
            fracs.append(f)
            unit_support.append(f)
        else:
            unit_support.append(None)
    support = float(np.mean(fracs)) if fracs else None
    covs, drops = [], []
    for pi, p in enumerate(pool):
        pu_s = units_of(p)[0]
        others = [q for qi, q in enumerate(pool) if qi != pi]
        maj = []
        for j in range(len(pu_s)):
            vals = []
            for q in others:
                if q == p:
                    vals.append(True)
                else:
                    r = pairs.get((p, q))
                    if r is not None:
                        vals.append(r["fwd"][j])
            vv = [v for v in vals if v is not None]
            if vv and sum(vv) / len(vv) >= 0.5:
                maj.append(j)
        if not maj:
            continue
        r = res[pi]
        cov_j = [(True if r is None else r["bwd"][j]) for j in maj]
        known = [v for v in cov_j if v is not None]
        n_unknown += len(cov_j) - len(known)
        if known:
            covs.append(sum(known) / len(known))
        for j, v in zip(maj, cov_j):
            if v is False:
                drops.append((pi, j, r["peer_units_r"][j]))
    coverage = float(np.mean(covs)) if covs else 1.0
    if support is None:
        g = None
    else:
        g = 1.0 if (support + coverage) == 0 else 1 - 2 * support * coverage / (support + coverage)
    eqs = [True if r is None else r["equiv"] for r in res]
    known_eq = [e for e in eqs if e is not None]
    c_nf = 1 - (sum(e is True for e in eqs) / n_peers)
    out.update(g_score=g, support=support, coverage=coverage, c_score_nf=c_nf, peer_unavailable=False,
               n_unknown=n_unknown, n_equiv_known=len(known_eq), unit_support=unit_support)
    codes = []
    if return_codes:
        peers_r = [cand_s if r is None else r["peer_r"] for r in res]
        for i, f in enumerate(unit_support):
            if f is None or f >= 0.5:
                continue
            u = cu[i]
            code = "ADD"
            if any(_majority_support(ent, peers_r, canon(v)) for v in _variants_neg(u)):
                code = "NEG"
            elif any(_majority_support(ent, peers_r, canon(v)) for v in _variants_quant(u)):
                code = "QUANT"
            elif any(_majority_support(ent, peers_r, canon(v)) for v in _variants_swap(u)):
                code = "SWAP"
            codes.append({"code": code, "unit": cu_s[i], "unit_index": i, "support": round(f, 3)})
        seen = set()
        for pi, j, us in drops:
            if us in seen:
                continue
            seen.add(us)
            codes.append({"code": "DROP", "unit": us, "peer_index": pi})
    out["unit_codes"] = codes
    out["top_code"] = next((c for c in CODE_PRIORITY if any(x["code"] == c for x in codes)), "NONE")
    return out


def g_from_subset(cand_s: str, pool: list[str], pairs: dict, ent: Entailer) -> float | None:
    """g_score with a restricted pool (used for the k=6 subsample check); no unit codes."""
    return graded_consensus(cand_s, pool, pairs, ent, return_codes=False)["g_score"]


def nf_medoid(pool: list[str], pairs: dict) -> int | None:
    """Index of the pool member NF-equivalent to the most other pool members (ties -> first)."""
    if not pool:
        return None
    best, bi = -1, None
    for i, a in enumerate(pool):
        n = sum(1 for j, b in enumerate(pool) if j != i and (a == b or (pairs.get((a, b)) or {}).get("equiv") is True))
        if n > best:
            best, bi = n, i
    return bi


# =================================================================================================== text side
L3_GATED = ["mm_role", "mm_claims", "mm_order", "missing_frac", "extra_frac"]  # exp A prereg L3_gated_fields


def l2_bow(text: str, fol_ast) -> dict:
    """L2-bow (exp A, unchanged): n_unanchored predicates + share of uncarried content words; continuous score = sum."""
    import fol_triage as FT
    r = FT.content_accounting(text, fol_ast)
    return {"l2_bow": r["n_unanchored"] + r["uncarried_frac"], "bow_n_unanch": r["n_unanchored"],
            "bow_uncarried": r["uncarried_frac"], "bow_flag": int(r["flag"]), "bow_unanchored": r["unanchored_preds"]}


def l3_z3(q: dict | None, fol_ast, prof: dict | None = None) -> dict:
    """L3 (exp A, unchanged): text questionnaire q vs the exact z3 role profile of the formula; score = sum of gated
    field mismatches. q None -> missing (caller imputes)."""
    import fol_triage as FT
    if prof is None:
        prof = FT.formula_role_profile(fol_ast)
    if q is None:
        return {"l3_z3": None, "l3_fields": None, "profile": prof}
    cmp = FT.l3_compare(q, prof)
    return {"l3_z3": FT.l3_score(cmp, L3_GATED), "l3_fields": {k: cmp.get(k) for k in FT.L3_FIELDS}, "profile": prof}


def text_side(text: str, fol_ast, q: dict | None, prof: dict | None = None, with_role: bool = True) -> dict:
    """All TEXT-side columns: l2_bow (+parts), l3_z3 (+fields), l1 lint codes, l2_role count (columns only)."""
    import fol_triage as FT
    out = {}
    t0 = time.time()
    out.update(l2_bow(text, fol_ast))
    try:
        l3 = l3_z3(q, fol_ast, prof)
        prof = l3.pop("profile")
        out.update(l3)
    except (z3.Z3Exception, RecursionError, KeyError, ValueError, TypeError) as ex:
        out.update(l3_z3=None, l3_fields=None, l3_err=str(ex)[:100])
    try:
        out["l1_codes"] = FT.fol_lint(fol_ast)["codes"]
    except (z3.Z3Exception, RecursionError, KeyError, ValueError, TypeError):
        out["l1_codes"] = None
    if with_role and prof is not None:
        try:
            ra = FT.role_accounting(text, fol_ast, prof)
            out["l2_role"] = sum(ra.get(k, 0) for k in ("cond_in_up", "assert_in_down", "pol_flip", "slot_swap", "exc_wrong"))
        except (RecursionError, KeyError, ValueError, TypeError, IndexError, AttributeError) as ex:
            out["l2_role"] = None
            out["l2_role_err"] = str(ex)[:80]
    out["secs_text"] = round(time.time() - t0, 3)
    return out


# =================================================================================================== fusion
def _z(x, mu, sd):
    return 0.0 if x is None else (x - mu) / (sd if sd > 0 else 1.0)


def apply_logistic(model: dict, feats: dict) -> float:
    """model = {'features', 'mean', 'sd', 'coef', 'intercept'}; missing feature -> z = 0."""
    s = model["intercept"]
    for f, m, sd, c in zip(model["features"], model["mean"], model["sd"], model["coef"]):
        s += c * _z(feats.get(f), m, sd)
    return 1 / (1 + math.exp(-s))


def fused_score(frozen: dict, feats: dict) -> dict:
    """Frozen PEER+TEXT fusion. Unparseable -> p_error 1.0. peer_unavailable -> frozen TEXT-only model (pre-registered).
    fired_signal = argmax standardized contribution (PEER = g/c_score_nf features, TEXT = l2_bow/l3)."""
    if feats.get("coverage_status") == "UNPARSEABLE":
        return {"p_error": 1.0, "flag": 1, "fired_signal": "UNPARSEABLE", "model_used": "none"}
    main = frozen["fusion"]
    use = main
    if feats.get("peer_unavailable") or feats.get(main["features"][0]) is None:
        use = frozen["text_only"]
    p = apply_logistic(use, feats)
    contrib = {f: c * _z(feats.get(f), m, sd) for f, m, sd, c in zip(use["features"], use["mean"], use["sd"], use["coef"])}
    top = max(contrib, key=contrib.get) if contrib else None
    sig = "PEER" if top in ("g_score", "c_score_nf", "c_score_align") else ("TEXT" if top else None)
    thr = main["threshold"] if use is main else frozen["text_only"]["threshold"]
    return {"p_error": p, "flag": int(p >= thr), "fired_signal": sig, "model_used": "fusion" if use is main else "text_only"}


def peer_text_score(text: str, fol: str, peers: list[str], frozen: dict, q: dict | None = None,
                    variant: str | None = None) -> dict:
    """One-call API: score candidate `fol` for `text` against a list of peer formalisations (other systems / families).
    q = cached L3 questionnaire of the text (None -> L3 missing, imputed z=0). Returns p_error, flag, fired_signal,
    unit_codes, g_score, c_score_nf, l2_bow, l3_z3, coverage_status."""
    variant = variant or frozen["variant"]
    tau = frozen["tau"].get(variant)
    e = parse_fol(fol)
    if e is None:
        return {"p_error": 1.0, "flag": 1, "coverage_status": "UNPARSEABLE", "fired_signal": "UNPARSEABLE"}
    cs = canon(e)
    ps = [canon(x) for x in (parse_fol(p) for p in peers) if x is not None]
    ent = Entailer(frozen["timeout_ms"])
    pairs = {}
    for a in [cs] + ps:
        for b in ps:
            if a != b and (a, b) not in pairs:
                pairs[(a, b)] = pair_result(a, b, ent, text=text, variant=variant, k=frozen["k"], tau=tau)
    gc_ = graded_consensus(cs, ps, pairs, ent)
    feats = {"g_score": gc_["g_score"], "c_score_nf": gc_["c_score_nf"], "peer_unavailable": gc_["peer_unavailable"]}
    feats.update(text_side(text, e, q, with_role=False))
    fs = fused_score(frozen, feats)
    return {**fs, "unit_codes": gc_.get("unit_codes"), "g_score": gc_["g_score"], "c_score_nf": gc_["c_score_nf"],
            "l2_bow": feats["l2_bow"], "l3_z3": feats.get("l3_z3"), "coverage_status": "OK"}

source_files.vendor_x8/vendor_c/common.py:
"""Shared primitives of the frozen screen: text normalisation, item ids, the automatic labeller,
equivalence-modulo-vocabulary (eqmv) and the complexity strata.

The labeller reproduces the iter-3 repair census (repair_census.work) stage by stage, so the label
vector is identical to sibling experiments A/B/D and dataset E (EQUIV+VOCAB -> CORRECT,
GRAN -> UNCERTAIN_GRAN, depth<=2 repair -> ERROR[ops], no repair -> UNCERTAIN_COMPOUND).
"""
from __future__ import annotations

import hashlib
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
sys.setrecursionlimit(10000)

from fol import equivalent, parse  # noqa: E402
from repair_census import align, atoms, fp, gran_bridge, search, toks  # noqa: E402

LLM_SYSTEMS = ["gpt-3.5-turbo", "gpt-4", "text-davinci-003"]
EXC_RE = re.compile(r"\b(unless|except|excluding|other than|apart from|but not|without)\b")
COARSE = {"ADD": "COVERAGE", "DROP": "COVERAGE", "NEG": "POLARITY", "REV": "POLARITY", "QUANT": "POLARITY"}


def norm(t: str) -> str:
    return re.sub(r"\s+", " ", re.sub(r"[^\w\s]", "", t.lower())).strip()


def item_id(system: str, text: str, fol: str) -> str:
    return hashlib.sha1((system + "|" + norm(text) + "|" + fol.strip()).encode()).hexdigest()[:16]


def safe_parse(s: str | None):
    if s is None or not str(s).strip():
        return None
    try:
        return parse(str(s))
    except (ValueError, IndexError, RecursionError, TypeError):
        return None


def vocab_strict(pmap: dict) -> bool:
    """Every renamed predicate pair has identical CamelCase token multisets."""
    return all(sorted(toks(k[0])) == sorted(toks(v)) for k, v in pmap.items())


def op_class(ops: list[str]) -> str:
    if not ops:
        return "NONE"
    cs = {COARSE.get(o, "STRUCT") for o in ops}
    return cs.pop() if len(cs) == 1 else "MIXED"


def label(cand: str, ref: str, ambiguous: bool = False, track: str = "L", budget_s: float = 25.0) -> dict:
    """LABEL(cand, ref, ambiguous) -> {label, auto_class, repair_ops, vocab_strict, pmap}.

    Stage order and z3 timeouts are those of repair_census.work (equivalent() default ms=5000)."""
    out = {"label": None, "auto_class": None, "repair_ops": [], "vocab_strict": None, "pmap": {}}
    ce, re_ = safe_parse(cand), safe_parse(ref)
    if re_ is None:
        out.update(label="REF_UNPARSEABLE", auto_class="REF_UNPARSEABLE")
        return out
    if ce is None:
        out.update(label="UNPARSEABLE", auto_class="UNPARSEABLE")
        return _reading(out, ambiguous, track)
    timeouts = False
    r = equivalent(ce, re_)
    if r is True:
        out.update(label="CORRECT", auto_class="EQUIV", vocab_strict=True)
        return out
    timeouts |= r is None
    ac, pmap, cmap = align(ce, re_)
    out["pmap"] = {f"{k[0]}/{k[1]}": v for k, v in pmap.items()}
    r = equivalent(ac, re_)
    if r is True:
        out.update(label="CORRECT", auto_class="VOCAB", vocab_strict=vocab_strict(pmap))
        return out
    timeouts |= r is None
    gb = gran_bridge(ac, re_)
    if gb:
        r = equivalent(gb[0], gb[1])
        if r is True:
            out.update(label="UNCERTAIN_GRAN", auto_class="GRAN")
            return _reading(out, ambiguous, track)
        timeouts |= r is None
    if timeouts:
        out.update(label="TIMEOUT_UNKNOWN", auto_class="TIMEOUT")
        return _reading(out, ambiguous, track)
    base, tgt = gb if gb else (ac, re_)
    ops, _ = search(base, tgt, budget_s=budget_s)
    if ops:
        out.update(label="ERROR", auto_class="+".join(ops), repair_ops=list(ops))
    else:
        out.update(label="UNCERTAIN_COMPOUND", auto_class="COMPOUND")
    return _reading(out, ambiguous, track)


def _reading(out: dict, ambiguous: bool, track: str) -> dict:
    """Track H: curator-flagged ambiguous items that are not CORRECT become READING_CHOICE."""
    if track == "H" and ambiguous and out["label"] != "CORRECT":
        out["underlying_label"] = out["label"]
        out["label"] = "READING_CHOICE"
    return out


# ------------------------------------------------------------------ equivalence modulo vocabulary
def _eq(a, b, ms):
    """z3 equivalence with the random-model fingerprint as a sound necessary-condition pre-filter."""
    if fp(a) != fp(b):
        return False
    return equivalent(a, b, ms=ms)


def eqmv(a, b, ms: int = 3000) -> tuple[bool | None, str]:
    """Symmetric equivalence modulo vocabulary: exact, then align() either direction, then gran_bridge."""
    to = False
    r = _eq(a, b, ms)
    if r is True:
        return True, "exact"
    to |= r is None
    for x, y in ((a, b), (b, a)):
        ax = align(x, y)[0]
        r = _eq(ax, y, ms)
        if r is True:
            return True, "align"
        to |= r is None
        gb = gran_bridge(ax, y)
        if gb:
            r = _eq(gb[0], gb[1], ms)
            if r is True:
                return True, "gran"
            to |= r is None
    return (None if to else False), "none"


# ------------------------------------------------------------------ strata
def _depth(e) -> int:
    k = e[0]
    if k == "atom":
        return 0
    if k in ("all", "ex"):
        return 1 + _depth(e[2])
    if k == "not":
        return 1 + _depth(e[1])
    return 1 + max(_depth(e[1]), _depth(e[2]))


def _count(e, kinds) -> int:
    k = e[0]
    n = 1 if k in kinds else 0
    if k == "atom":
        return n
    if k in ("all", "ex"):
        return n + _count(e[2], kinds)
    if k == "not":
        return n + _count(e[1], kinds)
    return n + _count(e[1], kinds) + _count(e[2], kinds)


def _conjuncts(e) -> int:
    return _conjuncts(e[1]) + _conjuncts(e[2]) if e[0] == "and" else 1


def _ncond(e) -> int:
    k = e[0]
    if k == "atom":
        return 0
    if k in ("all", "ex"):
        return _ncond(e[2])
    if k == "not":
        return _ncond(e[1])
    n = _conjuncts(e[1]) if k == "imp" else 0
    return n + _ncond(e[1]) + _ncond(e[2])


def strata(text: str, ref_fol: str) -> dict:
    words = len(text.split())
    e = safe_parse(ref_fol)
    m = EXC_RE.search(text.lower())
    out = {"words": words, "len_bin": "<12" if words < 12 else ("12-19" if words < 20 else ">=20"),
           "exception": bool(m), "exception_marker": m.group(1) if m else None}
    if e is None:
        out.update(n_quant=None, depth=None, n_cond=None)
    else:
        out.update(n_quant=_count(e, ("all", "ex")), depth=_depth(e), n_cond=_ncond(e))
    return out


def medoid_repair(c, m, budget_s: float = 10.0) -> tuple[int, list[str]]:
    """Minimal typed repair from candidate c to medoid m (after align + gran bridge)."""
    ac = align(c, m)[0]
    gb = gran_bridge(ac, m)
    base, tgt = gb if gb else (ac, m)
    ops, _ = search(base, tgt, budget_s=budget_s)
    return (len(ops), list(ops)) if ops else (3, ["COMPOUND"])


def alignable_frac(cand, ref) -> float | None:
    """Fraction of candidate predicates identical to, or align()-mapped onto, a reference predicate."""
    if cand is None or ref is None:
        return None
    from repair_census import symbols
    pc, _ = symbols(cand)
    pr, _ = symbols(ref)
    if not pc:
        return 1.0
    _, pmap, _ = align(cand, ref)
    ok = sum(1 for p in pc if p in pr or p in pmap)
    return ok / len(pc)

source_files.vendor_x8/vendor_c/repair_census.py:
"""MINIMAL-TYPED-REPAIR census of real NL->FOL errors (review critique 1 & 2 of iter 2).

For every curated FOLIO-conclusion / MALLS-test item whose ORIGINAL gold is not logically equivalent to the
CORRECTED gold (arXiv 2606.02837, HF DSAVlab-UNIUD), we ask: what is the SMALLEST sequence of typed edits that
turns the original into a formula equivalent to the corrected one, AFTER vocabulary alignment?

Stage 0  ALIGN   rename original predicates/constants onto corrected ones (same arity; CamelCase-token Jaccard
                 >= 0.5 or char-trigram Dice >= 0.6; constants by normalised string / containment).
                 equivalent after renaming                 -> VOCAB   (vocabulary only; not an error)
Stage 1  GRAN    definitional merge/split bridge: P(args) := Q1(args) & Q2(args) when tokens(P) == tokens(Q1)+tokens(Q2)
                 equivalent after bridge                   -> GRAN    (granularity only; not an error)
Stage 2  REPAIR  breadth-first search, depth <= 2, over typed operators applied to the aligned original:
                 NEG (insert/remove negation), REV (swap sides of ->), QUANT (forall<->exists), RESTR (-> <-> & directly
                 under a quantifier), CONN (other connective change among & | -> <-> xor), DROP (delete an operand of & / |),
                 ADD (conjoin an atom that exists only in the corrected formula), SWAP (permute arguments),
                 BIND (replace one argument by another in-scope variable or a corrected-formula constant),
                 SCOPE (swap adjacent quantifiers), UNGLUE (split independent generic claims out of one quantifier block).
                 A candidate is accepted when z3 proves it equivalent to the corrected formula; a cheap random-model
                 fingerprint pre-filters candidates. Items with no repair within depth 2 are COMPOUND.
The class of a real error is its operator multiset. Curators' AMBIGUITY flag is carried along, so 'reading choice'
corrections can be reported separately.
"""
import itertools
import json
import random
import re
import sys
import time
from collections import Counter
from pathlib import Path

from fol import parse, equivalent

D = Path("/ai-inventor/aii_data/runs/run_u75jRHUss0zo/iter_3/gen_hypo/claude_agent/data")  # read-only iter-3 data dir
TOKRE = re.compile(r"[A-Z]?[a-z]+|[A-Z]+(?![a-z])|\d+")
STOP = {"and", "or", "of", "in", "on", "the", "a", "an", "to", "is", "has", "have", "can", "for", "with", "by", "at", "from", "be", "are"}
BIN = ("and", "or", "imp", "iff", "xor")


def toks(name):
    out = []
    for w in TOKRE.findall(name.replace("_", " ")):
        w = w.lower()
        if w in STOP:
            continue
        out.append(w[:-1] if w.endswith("s") and len(w) > 3 else w)
    return out


def tri(s):
    s = re.sub(r"[^a-z0-9]", "", s.lower())
    return {s[i:i + 3] for i in range(max(1, len(s) - 2))}


def dice(a, b):
    A, B = tri(a), tri(b)
    return 2 * len(A & B) / max(1, len(A) + len(B))


# ---------------------------------------------------------------- AST utilities
def atoms(e, acc=None):
    acc = [] if acc is None else acc
    if e[0] == "atom":
        acc.append(e)
    elif e[0] in ("all", "ex"):
        atoms(e[2], acc)
    elif e[0] == "not":
        atoms(e[1], acc)
    else:
        atoms(e[1], acc); atoms(e[2], acc)
    return acc


def bound_vars(e, acc=None):
    acc = set() if acc is None else acc
    if e[0] in ("all", "ex"):
        acc.add(e[1]); bound_vars(e[2], acc)
    elif e[0] == "not":
        bound_vars(e[1], acc)
    elif e[0] != "atom":
        bound_vars(e[1], acc); bound_vars(e[2], acc)
    return acc


def symbols(e):
    bv = bound_vars(e)
    P, C = {}, set()
    for a in atoms(e):
        P[(a[1], len(a[2]))] = True
        for x in a[2]:
            if x not in bv:
                C.add(x)
    return set(P), C


def rename(e, pmap, cmap, bv=frozenset()):
    k = e[0]
    if k == "atom":
        return ("atom", pmap.get((e[1], len(e[2])), e[1]), tuple(x if x in bv else cmap.get(x, x) for x in e[2]))
    if k in ("all", "ex"):
        return (k, e[1], rename(e[2], pmap, cmap, bv | {e[1]}))
    if k == "not":
        return ("not", rename(e[1], pmap, cmap, bv))
    return (k, rename(e[1], pmap, cmap, bv), rename(e[2], pmap, cmap, bv))


def expand(e, defs):
    """defs: {(name, arity): [name1, name2]}  P(args) -> Q1(args) & Q2(args)"""
    k = e[0]
    if k == "atom":
        key = (e[1], len(e[2]))
        if key in defs:
            q = defs[key]
            out = ("atom", q[0], e[2])
            for n in q[1:]:
                out = ("and", out, ("atom", n, e[2]))
            return out
        return e
    if k in ("all", "ex"):
        return (k, e[1], expand(e[2], defs))
    if k == "not":
        return ("not", expand(e[1], defs))
    return (k, expand(e[1], defs), expand(e[2], defs))


def align(old, new):
    Po, Co = symbols(old)
    Pn, Cn = symbols(new)
    pmap, used = {}, set()
    cands = []
    for p in Po - Pn:
        for q in Pn - Po:
            if p[1] != q[1]:
                continue
            to, tn = set(toks(p[0])), set(toks(q[0]))
            j = len(to & tn) / max(1, len(to | tn))
            s = max(j, dice(p[0], q[0]))
            if p[0].lower() == q[0].lower():
                s = 2
            if j >= 0.5 or dice(p[0], q[0]) >= 0.6 or s == 2:
                cands.append((s, p, q))
    for s, p, q in sorted(cands, reverse=True):
        if p in pmap or q in used:
            continue
        pmap[p] = q[0]; used.add(q)
    cmap, cused = {}, set()
    norm = lambda s: re.sub(r"[^a-z0-9]", "", s.lower())
    for c in Co - Cn:
        best = None
        for d in Cn - Co:
            if d in cused:
                continue
            a, b = norm(c), norm(d)
            if a == b or (min(len(a), len(b)) >= 4 and (a in b or b in a)) or dice(c, d) >= 0.7:
                best = d
                break
        if best:
            cmap[c] = best; cused.add(best)
    return rename(old, pmap, cmap), pmap, cmap


def gran_bridge(ao, new):
    """Try merge/split definitional bridges between leftover predicates of the aligned original and corrected."""
    Po, _ = symbols(ao)
    Pn, _ = symbols(new)
    lo, ln = Po - Pn, Pn - Po
    defs_old, defs_new = {}, {}
    for p in lo:  # original merged predicate -> corrected split pair
        tp = sorted(toks(p[0]))
        for q1, q2 in itertools.combinations([q for q in ln if q[1] == p[1]], 2):
            if sorted(toks(q1[0]) + toks(q2[0])) == tp or set(toks(q1[0]) + toks(q2[0])) == set(tp):
                defs_old[p] = [q1[0], q2[0]]
    for q in ln:  # corrected merged predicate -> original split pair
        tq = sorted(toks(q[0]))
        for p1, p2 in itertools.combinations([p for p in lo if p[1] == q[1]], 2):
            if sorted(toks(p1[0]) + toks(p2[0])) == tq or set(toks(p1[0]) + toks(p2[0])) == set(tq):
                defs_new[q] = [p1[0], p2[0]]
    _, Cn = symbols(new)
    reify = {}
    for p in lo:  # P(x) := Q(x, c) when tokens(P) == tokens(Q) + tokens(c)
        for q in ln:
            if q[1] != p[1] + 1:
                continue
            for c in Cn:
                if set(toks(q[0]) + toks(c)) == set(toks(p[0])):
                    reify[p] = (q[0], c)
    if not defs_old and not defs_new and not reify:
        return None
    return reify_expand(expand(ao, defs_old), reify), expand(new, defs_new)


def reify_expand(e, reify):
    k = e[0]
    if k == "atom":
        key = (e[1], len(e[2]))
        if key in reify:
            q, c = reify[key]
            return ("atom", q, e[2] + (c,))
        return e
    if k in ("all", "ex"):
        return (k, e[1], reify_expand(e[2], reify))
    if k == "not":
        return ("not", reify_expand(e[1], reify))
    return (k, reify_expand(e[1], reify), reify_expand(e[2], reify))


# ---------------------------------------------------------------- random-model fingerprint (necessary condition)
SEEDS = list(range(24))


def ev(e, m, env, dom, seed):
    k = e[0]
    if k == "atom":
        args = tuple(env[x] if x in env else (hash((seed, "c", x)) % dom) for x in e[2])
        return (hash((seed, e[1], len(e[2]), args)) >> 3) & 1 == 1
    if k == "all":
        return all(ev(e[2], m, {**env, e[1]: d}, dom, seed) for d in range(dom))
    if k == "ex":
        return any(ev(e[2], m, {**env, e[1]: d}, dom, seed) for d in range(dom))
    if k == "not":
        return not ev(e[1], m, env, dom, seed)
    a, b = ev(e[1], m, env, dom, seed), ev(e[2], m, env, dom, seed)
    return {"and": a and b, "or": a or b, "imp": (not a) or b, "iff": a == b, "xor": a != b}[k]


def fp(e):
    return tuple(ev(e, None, {}, 3, s) for s in SEEDS)


# ---------------------------------------------------------------- typed operators
def subterms(e, path=(), scope=()):
    yield path, e, scope
    k = e[0]
    if k in ("all", "ex"):
        yield from subterms(e[2], path + (2,), scope + (e[1],))
    elif k == "not":
        yield from subterms(e[1], path + (1,), scope)
    elif k != "atom":
        yield from subterms(e[1], path + (1,), scope)
        yield from subterms(e[2], path + (2,), scope)


def replace(e, path, new):
    if not path:
        return new
    i = path[0]
    lst = list(e)
    lst[i] = replace(e[i], path[1:], new)
    return tuple(lst)


def parent_kind(e, path):
    if not path:
        return None
    x = e
    for i in path[:-1]:
        x = x[i]
    return x[0]


def unglue(node):
    """∀x∀y (A(x) ∧ B(y) → C(x) ∧ D(y))  ->  ∀x (A(x) → C(x)) ∧ ∀y (B(y) → D(y))"""
    vs, body = [], node
    while body[0] == "all":
        vs.append(body[1]); body = body[2]
    if len(vs) < 2 or body[0] != "imp":
        return None

    def conj(x):
        return conj(x[1]) + conj(x[2]) if x[0] == "and" else [x]

    def vars_of(x):
        return {a for at in atoms(x) for a in at[2] if a in vs}
    ant, con = conj(body[1]), conj(body[2])
    groups = []
    for v in vs:
        a = [x for x in ant if vars_of(x) == {v}]
        c = [x for x in con if vars_of(x) == {v}]
        if not c:
            return None
        groups.append((v, a, c))
    if sum(len(g[1]) for g in groups) != len(ant) or sum(len(g[2]) for g in groups) != len(con):
        return None

    def mk(lst, op="and"):
        out = lst[0]
        for x in lst[1:]:
            out = (op, out, x)
        return out
    parts = [("all", v, ("imp", mk(a), mk(c)) if a else mk(c)) for v, a, c in groups]
    return mk(parts)


def edits(e, target):
    """Yield (op_label, candidate) for every single typed edit of e."""
    tgt_atoms = atoms(target)
    Pe, _ = symbols(e)
    _, Ct = symbols(target)
    new_atoms = [a for a in tgt_atoms if (a[1], len(a[2])) not in Pe]
    for path, node, scope in list(subterms(e)):
        k = node[0]
        # NEG
        if k == "not":
            yield "NEG", replace(e, path, node[1])
        else:
            yield "NEG", replace(e, path, ("not", node))
        if k in ("all", "ex"):
            yield "QUANT", replace(e, path, ("ex" if k == "all" else "all", node[1], node[2]))
            # block flip with the restrictor convention: ∀x∀y(A→B) <-> ∃x∃y(A∧B)
            vs, body = [], node
            while body[0] == k:
                vs.append(body[1]); body = body[2]
            if body[0] in ("imp", "and"):
                nb = ("and" if body[0] == "imp" else "imp", body[1], body[2])
                q = "ex" if k == "all" else "all"
                for v in reversed(vs):
                    nb = (q, v, nb)
                yield "QUANT", replace(e, path, nb)
            if node[2][0] in ("all", "ex"):
                inner = node[2]
                yield "SCOPE", replace(e, path, (inner[0], inner[1], (k, node[1], inner[2])))
            ug = unglue(node) if k == "all" else None
            if ug is not None:
                yield "UNGLUE", replace(e, path, ug)
        if k in ("imp", "iff") and node[1][0] == "and":
            # MOVE: pull a conjunct of the left side out as an outer restriction: (A ∧ B op C) -> (A -> (B op C))
            yield "MOVE", replace(e, path, ("imp", node[1][1], (k, node[1][2], node[2])))
            yield "MOVE", replace(e, path, ("imp", node[1][2], (k, node[1][1], node[2])))
        if k == "imp" and node[2][0] == "imp":
            # MOVE inverse: A -> (B -> C)  <->  (A ∧ C) -> B style condition/consequence exchange
            yield "MOVE", replace(e, path, ("imp", ("and", node[1], node[2][2]), node[2][1]))
        if k in BIN:
            if k == "imp":
                yield "REV", replace(e, path, ("imp", node[2], node[1]))
            for op in BIN:
                if op != k:
                    lab = "RESTR" if {k, op} == {"imp", "and"} and parent_kind(e, path) in ("all", "ex") else "CONN"
                    yield lab, replace(e, path, (op, node[1], node[2]))
            if k in ("and", "or"):
                yield "DROP", replace(e, path, node[1])
                yield "DROP", replace(e, path, node[2])
        if k == "atom":
            args = node[2]
            if len(args) >= 2:
                for perm in set(itertools.permutations(args)):
                    if perm != args:
                        yield "SWAP", replace(e, path, ("atom", node[1], perm))
            pool = set(scope) | Ct
            for i, a in enumerate(args):
                for b in pool:
                    if b != a:
                        yield "BIND", replace(e, path, ("atom", node[1], args[:i] + (b,) + args[i + 1:]))
        # ADD: conjoin a corrected-only atom (args re-bound to in-scope variables when its variables are foreign)
        if k != "atom" or True:
            for a in new_atoms:
                sc = list(scope)
                opts = []
                for x in a[2]:
                    opts.append([x] if (x in Ct or x in sc) else (sc or [x]))
                for combo in itertools.islice(itertools.product(*opts), 6):
                    yield "ADD", replace(e, path, ("and", node, ("atom", a[1], tuple(combo))))


def search(ao, target, budget_s=25.0, max_d2=6000):
    ft = fp(target)
    t0 = time.time()
    lvl1 = []
    seen = set()
    for lab, c in edits(ao, target):
        s = str(c)
        if s in seen:
            continue
        seen.add(s)
        lvl1.append((lab, c))
        if fp(c) == ft and equivalent(c, target, ms=1500) is True:
            return [lab], time.time() - t0
    n = 0
    for lab1, c1 in lvl1:
        for lab2, c2 in edits(c1, target):
            n += 1
            if lab1 == "NEG" and lab2 == "NEG":
                continue
            if n > max_d2 * 10 or time.time() - t0 > budget_s:
                return None, time.time() - t0
            if fp(c2) == ft and equivalent(c2, target, ms=1500) is True:
                return sorted([lab1, lab2]), time.time() - t0
    return None, time.time() - t0


def load(p):
    return [json.loads(l) for l in open(p) if l.strip()]


def pairs():
    for r in load(D / "DSAVlab-UNIUD_MALLS_test_subset-CURATED__MALLS_instances.jsonl"):
        yield "MALLS", r["id"], r["NL_sentence"], r["FOL_sentence_old"], r["FOL_sentence_new"], str(r.get("ambiguity", "NA"))
    for r in load(D / "DSAVlab-UNIUD_FOLIO_validation-curated__FOLIO_instances.jsonl"):
        if str(r["id"]).startswith("story"):
            continue
        yield "FOLIO-concl", r["id"], r["NL_sentence"], r["FOL_sentence_old"], r["FOL_sentence"], str(r.get("ambiguity", "NA"))


def work(item):
    src, iid, nl, old, new, amb = item
    try:
        oe, ne = parse(old), parse(new)
    except Exception:
        return None
    if equivalent(oe, ne) is True:
        return None
    ao, pmap, cmap = align(oe, ne)
    rec = {"src": src, "id": iid, "nl": nl, "old": old, "new": new, "ambiguous": amb == "True",
           "pmap": {f"{k[0]}/{k[1]}": v for k, v in pmap.items()}, "cmap": cmap}
    if equivalent(ao, ne) is True:
        rec["cls"] = "VOCAB"; return rec
    gb = gran_bridge(ao, ne)
    if gb and equivalent(gb[0], gb[1]) is True:
        rec["cls"] = "GRAN"; return rec
    base, tgt = (gb if gb else (ao, ne))
    ops, dt = search(base, tgt)
    rec["secs"] = round(dt, 1)
    rec["cls"] = "+".join(ops) if ops else "COMPOUND"
    rec["depth"] = len(ops) if ops else None
    return rec


def main():
    from multiprocessing import Pool
    items = list(pairs())
    with Pool(2) as pool:
        recs = [r for r in pool.imap_unordered(work, items, chunksize=1) if r]
    out = Path(__file__).with_suffix(".rows.json")
    out.write_text(json.dumps(recs, ensure_ascii=False, indent=1))
    n = len(recs)
    c = Counter(r["cls"] for r in recs)
    print(f"non-equivalent pairs: {n}")
    for k, v in c.most_common():
        print(f"  {k:22s} {v:3d}  ({v/n:.2f})")
    vocab = sum(r["cls"] in ("VOCAB", "GRAN") for r in recs)
    err = [r for r in recs if r["cls"] not in ("VOCAB", "GRAN")]
    single = sum(r.get("depth") == 1 for r in err)
    two = sum(r.get("depth") == 2 for r in err)
    comp = sum(r["cls"] == "COMPOUND" for r in err)
    print(f"vocabulary/granularity-only (auto): {vocab}/{n}")
    print(f"remaining errors: {len(err)}  single-op: {single}  two-op: {two}  compound(>2 or unresolved): {comp}")
    ops = Counter(o for r in err if r.get("depth") for o in r["cls"].split("+"))
    print("operator mass among repaired errors:", dict(ops.most_common()))
    for amb in (True, False):
        sub = [r for r in recs if r["ambiguous"] == amb]
        print(f"ambiguous={amb}: n={len(sub)}", dict(Counter(r["cls"] for r in sub).most_common()))
    for s in ("MALLS", "FOLIO-concl"):
        sub = [r for r in recs if r["src"] == s]
        print(f"{s}: n={len(sub)}", dict(Counter(r["cls"] for r in sub).most_common()))


if __name__ == "__main__":
    sys.setrecursionlimit(10000)
    main()

